INSERT INTO `quiz_questions` VALUES ('UPLOAD-1792230579859-0001','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','教学楼一处安全出口被上锁，你第一步该做什么？','[\"立即告知楼宇值班人员或物业服务台，并通过校园渠道报修\",\"先问同学是否有人知道钥匙在哪\",\"在门上贴一张“暂不可用”的纸条\",\"等下次安全检查时再反映\"]',0,'出口锁闭会影响疏散。贴纸提醒不能替代报修，应让现场管理人员及时处置。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0002','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','晚自习时发现楼梯间应急照明损坏，怎么做最合适？','[\"等下次停电再确认是否真的损坏\",\"报告管理人员并提醒同学夜间注意\",\"请同学轮流用手机照亮楼梯\",\"只在班级群里说一声即可\"]',1,'应急照明故障要及时报修，不能用临时照明代替固定设施。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0003','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团活动布景挡住了教室出口标志，正确做法是？','[\"移开布景并保持标志可见\",\"在布景上写“出口”即可\",\"关灯后用手机照亮\",\"活动结束后再移\"]',0,'疏散指示必须清晰可见，活动布置不能遮挡。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0004','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在教学楼看见垃圾桶起火并开始蔓延，应如何报警？','[\"向119和校内值守人员报告具体地点、火势及人员情况\",\"等别人报\",\"先录完整视频\",\"只发朋友圈\"]',0,'准确位置与火势信息有利于及时救援。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0005','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现小范围火情，但自己未受过灭火器训练且出口在身后，第一步该做什么？','[\"硬着头皮扑救\",\"通知周围人员撤离并报警\",\"关灯继续上课\",\"把水倒在所有火源上\"]',1,'生命安全优先，不能为了扑救延误报警和撤离。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0006','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','走廊已有大量浓烟，最近的出口必须穿过烟区，较安全的选择是？','[\"从高层跳下\",\"闭眼冲过去\",\"寻找其他安全路线；无路可走则退回可隔烟处报警求救\",\"乘电梯\"]',2,'浓烟可能迅速致命，不能把“最近”误认为“最安全”。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0007','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','消防疏散演练到达集合点后，发现同组同学尚未出现。你会怎么做？','[\"独自返回楼内寻找\",\"先离开集合点\",\"替他向老师报到\",\"立即告知现场负责人其最后已知位置并配合清点\"]',3,'人员清点能帮助确认是否有人被困；未经现场指挥不得擅自返回危险区域。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0008','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','高层建筑外部有火情且楼梯不可用时，应如何求救？','[\"在相对安全区域报警并用灯光、醒目标识示意位置\",\"藏进衣柜\",\"打开所有门窗\",\"从窗外攀爬排水管\"]',0,'应避免高风险攀爬，保持通信并指明位置。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0009','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','灭火器喷射后火势仍在扩大，你会怎么做？','[\"继续靠近直到灭掉\",\"立即撤离并报警\",\"回去找第二个灭火器，不通知别人\",\"把门全打开\"]',1,'初起火灾无法控制时，应停止扑救，及时撤离。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0010','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','消防演练设置了模拟烟气，疏散路线仍可通行。按现场指挥撤离时，应怎样通过有烟区域？','[\"站直快跑，争取最先出去\",\"跟着人群走，不必辨认出口\",\"只要用湿毛巾捂住口鼻，就能穿过任何浓烟\",\"降低身体姿势，遮护口鼻，沿明确的安全路线有序撤离\"]',3,'烟气较轻且路线可通行时应低姿撤离；遮护口鼻不能保证穿过浓烟安全。若通道被浓烟或火势阻断，应改找安全路线或避险求救。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0011','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','消防演练中有人逆向返回取包，你会怎么提醒？','[\"按指挥继续疏散，不逆行取物\",\"从电梯返回\",\"等所有人走完再回去\",\"包比演练重要\"]',0,'逆行会扰乱疏散并增加拥堵风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0012','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新到一栋教学楼上课，花一分钟看疏散示意图的价值是？','[\"只需记住离教室最近的一个出口\",\"提前知道备用出口和集合地点\",\"发生火情时可以不听现场指挥\",\"可以根据示意图自行决定是否报警\"]',1,'预先了解备用出口，能在常走的通道受阻时少走弯路。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0013','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','楼内火情刚被扑灭，有同学想马上进去拿电脑。该怎么处理？','[\"马上进入\",\"等消防或现场负责人明确允许后再进入\",\"从侧门进入\",\"戴口罩即可\"]',1,'复燃、烟气和结构、电气风险可能仍存在。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0014','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','遇到火灾，你应该迅速向哪个方向逃生？','[\"着火相反的方向\",\"着火相应的方向\",\"人员多的方向\",\"安全出口的方向\"]',3,'应判断火势和烟气，沿可通行的疏散路线前往安全出口。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0015','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发生火灾的时候，应该（ ）？','[\"就地趴下来就行了\",\"按照安全出口的指示方向逃生\",\"向人员多的地方逃生\",\"向背与着火方向相反的方向逃生\"]',1,'按疏散指示寻找安全出口，同时确认路线没有被火或浓烟阻断。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0016','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','当遇到火灾时，要迅速向（ ）逃生。','[\"着火相反的方向\",\"人员多的方向\",\"安全出口的方向\",\"人员少的方向\"]',2,'应沿可用的安全疏散路线撤离。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0017','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】火灾发生时烟雾太浓可大声呼叫以吸引救援者的注意。','[\"正确\",\"错误\"]',1,'在浓烟中持续呼喊容易吸入烟气，应及时报警并采用适当方式求救。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0018','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】宿舍火灾时，若楼梯间有浓烟但仍能看清台阶，可以捂住口鼻弯腰快速通过。','[\"正确\",\"错误\"]',1,'能看清台阶不代表楼梯间安全，不应贸然进入浓烟区域。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0019','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','被困在着火的屋子里，实在没有办法逃生，只能等待救援，在下列（ ）里等待最为安全？','[\"客厅\",\"卧室\",\"书房\",\"卫生间\"]',3,'此类题通常考虑卫生间可能有水、便于封堵门缝。实际遇险应选择远离火烟、能够隔烟并对外求救的位置，不能一律躲进卫生间。（按本题选项）','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0020','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','教学楼响起火警警报，楼道内暂时没有明显烟雾。你应该怎么做？','[\"乘坐电梯快速下楼\",\"留在教室拍视频等待通知\",\"按照疏散指示从安全出口有序撤离，不乘坐电梯\",\"逆着人流返回取电脑\"]',2,'火灾时电梯可能断电、失控或进烟。应听从现场指挥，沿疏散指示和安全出口撤离，不返回取物，不拥挤推搡。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0021','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍门外出现浓烟，门把手明显发热，此时正确的处置方式是什么？','[\"关闭房门、封堵缝隙，报警说明位置并发出求救信号\",\"直接开门冲入烟雾\",\"乘坐电梯快速下楼\",\"从窗户直接跳下\"]',0,'门把手发热可能说明门外火势较大，贸然开门会让烟火涌入。应关门阻烟、拨打119说明位置，并在相对安全处等待救援；不可盲目冲入浓烟或跳楼。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0022','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学衣服被火焰引燃，现场没有灭火器。正确的做法是什么？','[\"让他快速奔跑寻找水源\",\"立即用塑料袋包住全身\",\"让他乘电梯下楼\",\"让他停下、就地躺倒并翻滚压灭火焰，同时呼救\"]',3,'奔跑会加速空气流动，使火势更大。应“停下—躺倒—翻滚”，并在保证施救者安全的情况下使用厚重衣物或灭火毯覆盖灭火，随后及时就医。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0023','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍有人把插线板电线绕在金属床架上，主要问题是？','[\"只有插线板接大功率电器时才有风险\",\"只要电线外皮看起来完整就没有问题\",\"线路受压磨损后可能漏电或短路\",\"用胶带把电线固定在床架上即可消除风险\"]',2,'电线长期受压、摩擦容易破损，碰到金属床架还会增加触电风险。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0024','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','为了桌面整洁，同学用衣物盖住正在使用的接线板。应如何处理？','[\"只要接线板没有发烫就先不动\",\"把衣物换成较薄的布\",\"把接线板移到床下继续使用\",\"移开可燃物并检查是否过热\"]',3,'衣物覆盖会妨碍散热，接线板也应远离床品等可燃物。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0025','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同一插线板同时连接多台高功率设备，怎么判断更合适？','[\"只要不跳闸就安全\",\"应停止超负荷用电并按宿舍规定使用\",\"每天轮换插线板即可\",\"插孔够就安全\"]',1,'超负荷可能使线路发热，不能仅以是否跳闸判断安全。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0026','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍停电，有人提出点蜡烛照明。你会怎么选？','[\"把蜡烛放在书桌上并有人看守\",\"只点几分钟，等手机充上电就熄灭\",\"用手机灯或应急照明，避免使用明火\",\"把蜡烛放在窗台上远离床铺\"]',2,'宿舍内不宜使用蜡烛，短时间使用或有人看守也不能消除明火风险。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0027','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','深夜宿舍烟感持续报警但暂未看到明火，怎么做最合理？','[\"只要闻不到烟就忽略\",\"关门用耳塞\",\"拆下烟感继续睡\",\"先确认安全、通知管理人员并按现场指示疏散\"]',3,'报警可能提示隐蔽火情或设备异常，应按程序核查，不能擅自屏蔽。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0028','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夏天把杀虫喷雾罐放在阳光直射的宿舍窗台上，怎么做最妥当？','[\"只要没有漏液就继续放\",\"用毛巾盖住罐体，仍放在窗台\",\"移到符合产品要求的阴凉处，远离热源\",\"等罐体变烫后再挪走\"]',2,'气雾罐受热后内部压力可能升高，应按标签要求避光、远离热源存放。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0029','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团布置展台，准备把多根插线板串接供灯具使用。该怎么处理？','[\"请场地管理人员核定用电方案，避免串接超负荷\",\"用地毯盖住线路\",\"串接越多越方便\",\"只要有人看守就可以\"]',0,'临时用电需评估负荷和线路敷设，串接插线板易造成隐患。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0030','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍里电熨斗仍通电，同学准备去食堂。该怎么处理？','[\"调到最低档后离开\",\"请室友隔一会儿看一眼\",\"断电并确认冷却后离开\",\"放在桌面中央，避开衣物即可\"]',2,'离开前应断开电源并确认冷却，不把带电发热电器留给无人看管的宿舍。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0031','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','自习室把海报箱长期堆在配电箱前，主要风险是什么？','[\"配电箱的日常操作会更慢\",\"只会影响卫生检查\",\"纸箱放得整齐就没有问题\",\"妨碍紧急断电和维护，增加可燃物\"]',3,'配电箱前要留出操作空间，周边也不宜堆放纸箱等可燃物。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0032','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','全国消防日是（ ）。','[\"1月19日\",\"11月9日\",\"9月11日\",\"11月19日\"]',1,'全国消防日是11月9日。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0033','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】禁止在具有火灾、爆炸危险的场所使用明火。','[\"正确\",\"错误\"]',0,'明火可能引燃可燃物或可燃气体。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0034','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些做法可以有效预防宿舍火灾？','[\"不在宿舍吸烟或使用明火\",\"定期检查电线、插座是否老化\",\"将电动车电池带入室内充电\",\"手机充电完成后及时拔掉充电器\"]',0,'电动车电池不应带入宿舍充电。','approved','2026-10-17 09:49:41','[0,1,3]'),('UPLOAD-1792230579860-0035','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','大学生宿舍内，对电器的使用以下说法正确的是？','[\"根据宿舍配备的最大电功率使用\",\"一律不准使用电器\",\"按照学校的规定要求使用\",\"只要是检测合格的电器就能使用\"]',2,'宿舍电器的使用应遵守学校规定。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0036','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','睡前，小周把正在充电的手机压在枕头下面，准备第二天早上再拔。你应当怎样提醒他？','[\"把手机放在通风、远离可燃物的位置充电，并避免长时间无人看管\",\"只要使用原装充电器就绝对安全\",\"用被子盖住手机，防止屏幕光影响睡眠\",\"将手机和充电宝同时放在床上充电\"]',0,'充电设备工作时会发热，枕头、被褥等会影响散热且属于可燃物。应在通风、干燥、远离可燃物的位置充电，发现异常发热、鼓包或异味应立即停止使用。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0037','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍插排突然发热并伴有焦糊味，最合适的第一步是什么？','[\"继续使用，观察一会儿再说\",\"在确保安全的前提下立即断电，停止使用并联系宿管或专业人员处理\",\"用水给插排降温\",\"用纸巾包住插排，防止气味扩散\"]',1,'发热和焦糊味可能是过载、接触不良或短路的信号。应先切断电源并停止使用，不能带电泼水，也不能继续通电试验。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0038','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','最后一名同学离开宿舍前，哪项做法最稳妥？','[\"只关闭照明灯\",\"让充电设备继续在床上工作\",\"用纸箱遮住插排\",\"关闭违规或非必要电器电源，检查门窗后离开\"]',3,'离开宿舍前应关闭非必要电器和电源，检查门窗，避免设备长时间无人看管。充电设备不应放在床铺等可燃物附近。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0039','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现室友正在宿舍使用无自动断电保护的电炉，正确做法是？','[\"开窗后可以继续使用\",\"提醒立即停止使用，并按宿舍管理要求处理\",\"只在白天使用就安全\",\"把电炉放到床下隐藏\"]',1,'违规大功率或明火类电器可能造成线路过载和火灾。应立即停止使用，并通过宿管、辅导员等正规渠道处理。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0040','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍楼常闭式防火门被楔子长期撑开，应如何处理？','[\"移除楔子并报告管理人员\",\"白天人多时撑开，晚上再关闭\",\"只在消防检查前关闭\",\"在门旁放一个灭火器即可继续撑开\"]',0,'常闭式防火门需要保持关闭，才能在火情中阻隔烟火。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0041','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现走廊手动火灾报警按钮外壳破损，该怎么处理？','[\"先观察几天，看是否有人报修\",\"只在群里提醒同学不要触碰\",\"自行按压测试是否还能报警\",\"记录位置并报告楼宇管理人员\"]',3,'报警按钮损坏应由管理人员检查维修，学生不要自行测试或拆修。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0042','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','教室吊顶喷淋头被气球和横幅遮住，为什么要调整？','[\"气球会使喷淋头自动喷水\",\"遮挡可能妨碍消防设施发挥作用\",\"因为所有横幅都不能挂在教室\",\"因为喷淋头平时需要人工操作\"]',1,'装饰物遮挡喷淋头可能影响其正常工作，应留出必要空间。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0043','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','志愿活动使用校内厨房，看到排烟罩积油明显，该怎么处理？','[\"用纸擦一下即可\",\"多开风扇继续用\",\"向食堂管理人员报告并安排清洁维护\",\"直接用水冲电机\"]',2,'油垢积累增加厨房火灾风险，应由管理人员规范维护。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0044','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在消防实操训练中，使用手提式干粉灭火器扑救可控的初起固体物火灾，喷管应对准哪里？','[\"火焰上方\",\"烟最浓的位置\",\"着火点周围未燃烧的地面\",\"火焰根部\"]',3,'受训人员应在确保退路、站位安全的前提下，提起灭火器、拔保险销、握喷管、压把手，对准火焰根部喷射。火势扩大时立即撤离并报警。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0045','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','活动主持人借走走廊灭火器给舞台拍摄使用。你会怎么做？','[\"制止挪用并联系场地管理人员\",\"只借空瓶\",\"把位置标记在地图上\",\"拍完放回就好\"]',0,'消防器材需在固定位置保持可用。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0046','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你发现走廊里的消火栓前堆放了多个快递箱，正确处理方式是？','[\"只要还能看见消火栓就不用管\",\"及时提醒清理，并通过宿管或隐患上报渠道反映\",\"将箱子推到安全出口旁边\",\"等到消防检查前再清理\"]',1,'消防设施和疏散通道必须随时保持可接近、可使用状态。把杂物移到安全出口附近仍会形成新的疏散隐患。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0047','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','检查常见干粉灭火器时，压力表指针位于哪个颜色区域通常表示压力正常？','[\"绿色区域\",\"红色区域\",\"任何区域\",\"指针不动即可\"]',0,'常见灭火器压力表指针位于绿色区域通常表示压力正常；红色一般表示压力不足。实际使用前还应检查铅封、有效期和外观。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0048','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','雨天有人想把电动自行车推进楼道避雨，较妥当的建议是？','[\"停在疏散通道角落\",\"停到规定的室外停放区\",\"只要不充电就能停\",\"停在楼梯下\"]',1,'楼道和疏散通道应保持畅通，电动自行车应按规定停放。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0049','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电动自行车原配充电器损坏，同学拿来电压规格不明的充电器。你会怎么提醒？','[\"插头能插上就行\",\"先充五分钟试试\",\"核对设备与充电器规格，使用合规匹配产品\",\"充电时盖住电池\"]',2,'不匹配的充电设备可能造成过热及电池故障。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0050','消防安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','充电宝出现明显鼓包但还能正常充电，应该怎么办？','[\"继续使用到完全损坏\",\"用针扎破鼓包放气\",\"立即停用，避免挤压、撞击和继续充电，按规定交由合适渠道处理\",\"放进冰箱降温\"]',2,'鼓包说明电池可能已经损坏，继续充电或刺破都可能引发起火、爆炸。应停止使用并按电子废弃物或学校相关规定安全处置。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0051','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑行时双耳戴降噪耳机听歌，主要风险是？','[\"难以及时听到鸣笛和警示\",\"影响步数统计\",\"会让车胎漏气\",\"电量下降\"]',0,'骑行需要持续感知周围声音和交通变化。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0052','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夜间骑车经过较暗道路，哪种做法更利于他人发现你？','[\"关闭车灯\",\"使用合规车灯和反光装置\",\"穿全黑衣且不减速\",\"只看手机导航\"]',1,'照明和反光可改善可见性，仍需控制车速。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0053','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','抱着一大箱物品骑自行车，箱子挡住前方视线。该怎么处理？','[\"继续慢骑\",\"改用安全方式运送，保持骑行视线和操控\",\"单手扶车把\",\"让同伴从旁指挥\"]',1,'挡视线、妨碍操控的载物方式会增加事故风险。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0054','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','不熟悉津南校区路线，需要查看导航。骑车时该怎么处理？','[\"逆向骑行以便看路牌\",\"边骑边看\",\"在安全位置停车后查看\",\"让同伴把手机举在眼前\"]',2,'骑行中看屏幕会分散注意力。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0055','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','戴头盔但没有系紧系带，主要问题是？','[\"影响外观\",\"碰撞时头盔可能移位或脱落\",\"只影响速度\",\"头盔会更透气\"]',1,'正确佩戴并固定头盔才能发挥保护作用。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0056','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑车出发前发现前刹车手柄松软无力，该怎么处理？','[\"骑得快些减少制动\",\"只用后刹车照常骑\",\"停止骑行并维修后再用\",\"下坡时用脚拖地\"]',2,'制动故障会显著增加碰撞风险。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0057','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','下雨时单手撑伞骑车，最主要的风险是？','[\"伞会被淋湿\",\"影响操控和视野\",\"鞋子更容易脏\",\"速度会过慢\"]',1,'应选择合适雨具并保持双手有效控制车辆。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0058','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是正确的骑行行为？','[\"佩戴头盔\",\"逆行\",\"不闯红灯\",\"不随意变道\"]',0,'逆行、闯红灯和随意变道容易引发事故。','approved','2026-10-17 09:49:41','[0,2,3]'),('UPLOAD-1792230579860-0059','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑自行车正确的做法是？','[\"单手扶把\",\"双手扶把\",\"不需要非得扶把\",\"轮换交替\"]',1,'双手扶把有助于保持平衡并及时控制车辆。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0060','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑行途中收到紧急消息，应该如何处理？','[\"单手骑车，低头快速回复\",\"在不妨碍通行的安全位置停车后再查看和回复\",\"戴耳机听语音并继续骑行\",\"让后座同学代为控制车把\"]',1,'骑行时看手机会显著分散注意力并影响操控。应先安全停车，再处理消息，不能边骑边看或把车辆控制交给他人。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0061','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夜间骑自行车经过照明较暗的道路，怎样做更安全？','[\"使用有效照明和反光装置，减速观察路况\",\"关闭车灯以节省电量\",\"穿深色衣物并快速通过\",\"戴耳机听导航并高速骑行\"]',0,'夜间视线和可见性较差，应使用照明、反光装置并降低速度，避免戴耳机或分心操作。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0062','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','已办校园电动自行车通行证，但车辆换了，怎么做最妥当？','[\"用照片替代\",\"旧证直接装新车\",\"按保卫处流程更新车辆登记\",\"借同学的证\"]',2,'人车登记信息应保持一致。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0063','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学想借你的校园电动自行车通行证使用一周，你会怎么做？','[\"只借照片\",\"收押金后借\",\"借给他\",\"拒绝并提醒其按规定办理\"]',3,'通行证与登记人、车辆相关，借用会造成管理信息失真。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0064','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校门附近的人行便道因施工封闭，你会怎么做？','[\"按临时指引绕行\",\"从机动车道逆行\",\"推倒围挡\",\"跨过围挡抄近路\"]',0,'施工围挡内可能有机械、沟槽和坠物风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0065','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','前一位同学刷码过闸后，门尚未关闭，你会怎么做？','[\"跟着冲过去\",\"用自己的有效身份方式依次通行\",\"从侧边挤过\",\"请他替你刷\"]',1,'一人一闸有助于保障校园门禁秩序和出入安全。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0066','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑车到有视觉遮挡的校园路口，你会怎么做？','[\"跟随前车不观察\",\"直接冲出\",\"减速观察两侧，确认安全再通过\",\"仅听有没有鸣笛\"]',2,'树木和停放车辆会遮挡来车与行人。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0067','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','下课后想从停着的校车车头前横穿道路，该怎么处理？','[\"让司机按喇叭\",\"边跑边看手机\",\"贴车头快速穿行\",\"绕至视线清楚的合规过街位置，确认来车\"]',3,'车头遮挡视线，会形成行人和驾驶人的双向盲区。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0068','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','机动车驶入校园，路旁有限速标志。驾驶人该怎么处理？','[\"遵守标志限速并注意行人\",\"只在保安面前减速\",\"跟着前车速度开\",\"按道路空旷程度自行决定\"]',0,'校园行人密集，驾驶人应遵守校内交通管理要求。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0069','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电动自行车尚未取得校园通行证，但已有社会道路牌照。能否在南开校内通行停放？','[\"请门卫口头同意即可\",\"可以直接通行\",\"须依照学校要求办理校园通行证\",\"只在夜间可以\"]',2,'学校明确要求在校内行驶、停放的电动自行车依规办理校园通行证。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0070','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','车棚有空位，学生却把车停在盲道上，正确做法是？','[\"贴告示说明\",\"只留半条盲道\",\"停一会儿无妨\",\"移至指定车位\"]',3,'盲道应保持可通行，车辆应停在规定区域。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0071','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','人流密集的校内过街路口，骑车通过已明显妨碍行人。怎么做更妥当？','[\"从人群缝隙加速\",\"逆行绕开\",\"持续鸣铃挤过去\",\"下车推行并礼让行人\"]',3,'行人密集时推行更容易控制车辆并减少碰撞。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0072','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','前方50米才有允许掉头的位置，逆行能少绕路。正确选择是？','[\"按道路规定行驶，到合适位置转向\",\"在人行道快速骑\",\"开手机闪光灯逆行\",\"逆行但速度慢\"]',0,'逆行会与正常交通流形成冲突。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0073','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校门口人、车同时汇入，你骑车时该怎么处理？','[\"跟着机动车尾部挤进\",\"横穿隔离设施\",\"靠鸣铃抢行\",\"减速观察、按指示通行并礼让行人\"]',3,'混行区域冲突点多，应减速并遵守现场标识。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0074','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校内电动自行车管理要求近期调整，最可靠的信息来源是？','[\"去年的同学经验\",\"短视频评论\",\"匿名群聊截图\",\"保卫处官网最新通知和办理窗口\"]',3,'具体校内规则可能更新，应以保卫处正式通知为准。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0075','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】电动自行车可以不登记上牌。','[\"正确\",\"错误\"]',1,'电动自行车上路应遵守当地登记上牌规定。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0076','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在未设停放点的地方停放自行车时，应在（ ）停放。','[\"不妨碍通行的地点\",\"不经常使用的盲道\",\"草坪绿地\",\"任意地点\"]',0,'停车不能妨碍通行，也不应占用盲道。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0077','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学新买了一辆电动自行车，准备直接骑入校园。怎么做更规范？','[\"只要戴头盔就可以直接入校\",\"借用他人的校园通行证\",\"按学校现行规定完成车辆登记和校园通行手续后再入校\",\"遮挡车辆信息后从偏门进入\"]',2,'南开大学现行交通管理强调电动自行车准入、登记和校园通行管理。不得冒用、转借通行凭证，也不应使用不符合标准的车辆。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0078','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电动自行车电量不足，宿舍楼下没有空余充电位。怎么做最合适？','[\"把电池带进宿舍充电\",\"从寝室窗口拉线到楼下充电\",\"把车停在安全出口旁临时充电\",\"等待或寻找其他指定充电区域，不入楼、不飞线充电\"]',3,'电动自行车及电池入楼、飞线充电和占用疏散通道都会增加火灾风险。应在指定区域使用符合要求的设施充电。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0079','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑自行车经过下课时段的教学楼门口，行人很多。正确做法是？','[\"减速慢行，必要时下车推行并礼让行人\",\"连续鸣铃并高速穿过\",\"从人群缝隙中快速穿行\",\"逆向绕开人群\"]',0,'人车混行区域应减速、观察并礼让行人。视线受阻或人员密集时，下车推行比强行穿越更安全。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0080','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','驾车在校园道路行驶时，前方有学生准备过斑马线。驾驶人应当怎么做？','[\"加速抢在学生前通过\",\"鸣笛要求学生让路\",\"从非机动车道绕行\",\"减速或停车让行，并遵守校园限速和停车规定\"]',3,'校园道路行人密集，机动车应限速、规范停放并主动礼让行人。抢行、占用非机动车道或违规停车都会增加事故风险。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0081','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','教学楼门口的非机动车停放区已满，正确做法是？','[\"停在消防通道内\",\"寻找其他指定停放区域，不占用通行和消防空间\",\"停在盲道或无障碍坡道上\",\"锁在安全出口门把手上\"]',1,'车辆应在指定区域规范停放，不得占用消防通道、盲道、无障碍设施和安全出口。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0082','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','雨天校园路面湿滑，骑车接近路口时该怎么处理？','[\"紧贴前车\",\"保持原速急刹\",\"提前减速、增大跟车距离\",\"边打伞边加速\"]',2,'湿滑路面制动距离可能增加，应提前降速。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0083','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','大型车辆准备右转，你骑车在其右侧靠近车身，最安全的做法是？','[\"按喇叭并行\",\"抓住车尾慢行\",\"抢先通过\",\"远离车辆盲区并等待其转弯完成\"]',3,'大型车辆转弯存在内轮差和盲区。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0084','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','把车停在斑马线前的路口转角，会带来什么问题？','[\"方便找车\",\"遮挡行人与车辆互相观察\",\"能增加车流速度\",\"没有影响\"]',1,'路口违法或不规范停车可能造成视线盲区。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0085','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园摆渡车尚未停稳，有人准备跳下车。你会怎么提醒？','[\"等车辆停稳并按顺序下车\",\"把包先扔下去\",\"从后窗下\",\"动作快一点\"]',0,'未停稳下车易跌倒或卷入车辆周边危险区域。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0086','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电动自行车骑行中闻到电池仓异味并出现异常发热，该怎么处理？','[\"在安全位置停车、断电并远离，联系管理人员处理\",\"用水直接冲电池仓\",\"把车推进楼道\",\"继续骑到宿舍\"]',0,'异常发热与异味可能提示电池故障，应停止使用并避免靠近可燃物。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0087','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','走在停车场内，一辆车开始倒车且司机似乎没看见你。你会怎么做？','[\"拍车窗提醒\",\"站在倒车轨迹中等待\",\"从车尾贴身穿过\",\"保持距离并等车辆停稳后通过\"]',3,'倒车区域可能存在视线盲区，应主动避让。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0088','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑行经过路边刚停下的汽车，应该怎么做？','[\"只看车轮\",\"紧贴车门加速\",\"留足侧向距离，留意车门突然开启\",\"拍打车门\"]',2,'开门碰撞是近距离通过停靠车辆的常见风险。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0089','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园内两车发生剐蹭，有人受伤但暂无火险。你会怎么做？','[\"报警求助并保护现场，优先照顾伤者安全\",\"立即在群里公布责任人\",\"让双方私下离开\",\"先挪走所有物品避免围观\"]',0,'应优先救助、报警并保留必要现场信息。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0090','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','乘坐校外网约车前排短途出行，该怎么处理？','[\"路近不用系\",\"系好安全带并确认车辆信息\",\"只在高速系\",\"把安全带放在身后\"]',1,'短途也可能发生急刹或碰撞，乘车前应核验车辆。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0091','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','下课后教学楼出口人流密集，你骑车经过出口旁的道路。怎么做最稳妥？','[\"连续鸣铃让行人避开\",\"贴着人群边缘慢慢骑过\",\"提前减速，必要时下车推行，礼让横穿的行人\",\"跟在前车后面直接通过\"]',2,'课间高峰容易出现行人突然转向或横穿。仅靠鸣铃不能代替减速观察和让行。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0092','交通安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你骑车与行人发生碰撞，对方表示腿部疼痛。正确做法是？','[\"认为问题不大，立即离开\",\"立即扶对方快速走动\",\"先保障现场安全，查看伤情，必要时拨打120并联系校园安保\",\"先删除行车记录再协商\"]',2,'发生事故后应立即停车、保护人员安全、及时求助并配合处理。对疑似骨折或严重受伤者不要随意搬动，以免造成二次伤害。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0093','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在食堂捡到一张含姓名和学号的校园卡，最妥当的是？','[\"交给食堂服务台或学校失物招领渠道\",\"借卡消费后归还\",\"带回宿舍收藏\",\"拍正反面发公开群\"]',0,'通过正规失物招领渠道归还，同时避免公开个人信息。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0094','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你把快递取件码截图发到公开群里求同学代取，主要风险是？','[\"取件码会自动失效\",\"快递员会迟到\",\"他人可能凭码冒领\",\"箱子会变重\"]',2,'取件码属于可用于领取物品的信息，应只提供给可信代取人。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0095','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','体育馆更衣室储物柜门锁损坏，你会怎么做？','[\"仍把钱包放里面\",\"更换可用柜位并报修\",\"只把柜门推紧\",\"请陌生人照看\"]',1,'明知锁具失效时不宜继续存放贵重物品。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0096','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','骑共享单车到宿舍后发现车筐里有别人的钱包，该怎么处理？','[\"联系平台或交学校失物招领渠道\",\"翻看证件后私自联系家属要酬金\",\"放在路边\",\"留作纪念\"]',0,'通过可靠渠道移交，保护失主财产与个人信息。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0097','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','从图书馆出来发现背包不见了，第一步该做什么？','[\"等三天再找\",\"立即指认邻座\",\"向馆员和保卫人员报告，提供时间、位置和物品特征\",\"在网上公布所有同学照片\"]',2,'准确线索有利于核查，不能无证据指认他人。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0098','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','捡到一串标有宿舍楼号的钥匙，该怎么处理？','[\"挂在楼外明显处\",\"留给自己备用\",\"直接插门试是哪间\",\"交宿管或失物招领处\"]',3,'不要尝试进入他人空间，交由管理人员寻找失主。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0099','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你准备离开图书馆座位十分钟，桌上放着笔记本电脑和证件。怎么做更安全？','[\"用一本书盖住电脑即可\",\"请陌生同学帮忙看管\",\"随身带走贵重物品和证件，或使用可靠的保管措施\",\"只带走充电器\"]',2,'公共场所人员流动大，短暂离开也可能发生物品遗失或被盗。证件与贵重物品应随身携带，不能仅靠遮挡或口头托付。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0100','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现校园卡和身份证同时遗失后，首先应该怎么做？','[\"在公开群里发布完整身份证照片寻找\",\"及时挂失校园卡和相关账户，并按规定补办、报警或备案\",\"等几天看看是否有人归还\",\"借用同学账号继续使用校园服务\"]',1,'证件遗失可能带来冒用和财产风险，应尽快挂失并补办。寻物信息中不要公开完整证件号码、住址等敏感信息。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0101','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夜间有陌生人反复在宿舍门口观察并尝试尾随进入，你会怎么做？','[\"独自质问\",\"保持距离，通知宿管或保卫人员\",\"替其刷门禁\",\"拍视频追上去\"]',1,'让有职责的人员核验身份，避免独自发生冲突。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0102','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学说借你的学生证帮校外朋友进楼，正确做法是？','[\"让朋友趁人多进入\",\"借给他\",\"拒绝并引导按访客规定登记\",\"只借照片\"]',2,'证件和门禁权限不应转借。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0103','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍钥匙丢失后，合适的第一步是？','[\"等有人捡到\",\"按宿舍管理流程报告并采取补配或换锁措施\",\"把备用钥匙放门垫下\",\"用胶带封锁孔\"]',1,'钥匙丢失可能影响宿舍安全，应及时处理。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0104','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验楼共享办公室最后一人离开，却发现门无法锁闭，该怎么处理？','[\"让路过同学帮忙\",\"直接离开\",\"联系管理人员处理并妥善看护室内物品\",\"把门虚掩\"]',2,'共享办公空间也应落实门窗和财物管理。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0105','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人自称维修人员，未经预约要求进入宿舍检查线路，该怎么处理？','[\"让其独自进房\",\"提供宿舍密码\",\"直接开门\",\"通过宿管或报修记录核实身份和任务\"]',3,'维修人员身份和工作安排应由正规管理渠道确认。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0106','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','宿舍门禁无法正常闭合，任何人都能进入。你会怎么做？','[\"把门完全打开\",\"等宿管发现\",\"及时报修并提醒室友提高警惕\",\"贴一张纸写“请关门”即可\"]',2,'门禁失效属于应及时处理的安全隐患。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0107','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','朋友要你把自己的入校二维码截图发给他使用，该怎么处理？','[\"拒绝并引导使用本人有效入校方式\",\"发旧截图\",\"先问用途再给\",\"立即发送\"]',0,'身份凭证不能共享，出入应按学校门禁规定核验。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0108','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','深夜有人敲宿舍门称“送错外卖”，要求你开门帮他查房号。你会怎么做？','[\"让他进屋查\",\"直接开门\",\"隔门沟通并请其联系宿管或订单本人\",\"把手机交给他\"]',2,'保持门禁边界，并通过管理人员核实。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0109','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你刷门禁进入宿舍楼时，陌生人称“忘带卡了”并想跟随进入。应该怎么做？','[\"请他联系被访同学或宿管核验身份，不替陌生人放行\",\"出于礼貌替他拉住门\",\"让他报出任意一个宿舍号即可\",\"把自己的门禁卡借给他\"]',0,'尾随进入会绕过门禁管理。来访人员应按规定登记并由相关人员核验，门禁卡不得转借。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0110','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学想让校外朋友未经登记在宿舍留宿一晚，正确做法是？','[\"遵守宿舍和校园治安管理规定，不擅自留宿外来人员\",\"只住一晚不需要登记\",\"借用室友身份登记\",\"等宿管检查时再离开\"]',0,'宿舍人员管理关系到全楼安全。来访人员应按规定登记，不能冒用身份或擅自留宿。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0111','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','教学楼角落出现无人认领、外观异常的包裹，你会怎么做？','[\"远离并通知楼宇管理和保卫人员\",\"踢到垃圾桶\",\"拿到人多处询问\",\"拆开看看\"]',0,'不明物品应交专业人员判断，不随意移动。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0112','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校外陌生人说自己走失，要求你单独带他去偏僻楼宇。你会怎么做？','[\"把手机交给对方\",\"跟随对方上车\",\"立刻陪同\",\"在安全公共区域联系保卫人员或警方协助\"]',3,'帮助他人也应保持自身安全，适合交由有职责的人员处理。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0113','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夜间结束社团活动后手机电量很低，回宿舍路线偏僻。怎么做更妥当？','[\"关闭定位继续独行\",\"搭陌生人的车\",\"走最短暗路\",\"选择照明良好的路线，必要时结伴\"]',3,'路线和结伴安排可以降低夜间独行风险。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0114','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','晚上看到围挡后有近路可走，但地面不平。你会怎么做？','[\"沿开放道路绕行\",\"打开围挡门\",\"让同伴先试路\",\"翻越围挡\"]',0,'施工区域可能有坑洞、设备和坠落风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0115','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现陌生人在实验楼外试图撬门，且你距其较近。第一步该做什么？','[\"独自上前抓住他\",\"离开危险范围并立即联系保卫人员\",\"站在旁边质问\",\"把门打开查看\"]',1,'不自行对抗可疑人员，及时报告位置与行为。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0116','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','夜间独自返校时，你发现身后的人在多次转弯后仍跟随。正确做法是？','[\"独自走进偏僻小路试探对方\",\"停下来与对方争论\",\"戴上耳机假装没发现\",\"前往明亮、人多或有安保人员的区域，联系同伴或报警求助\"]',3,'遇到疑似尾随，应优先拉开距离、进入安全区域并及时求助，避免进入偏僻地带或与可疑人员正面冲突。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0117','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','看见两名学生发生肢体冲突，你会怎么选？','[\"保持安全距离，呼叫保卫或现场管理人员\",\"直播围观\",\"抢走双方手机\",\"加入一方\"]',0,'避免扩大冲突，由受过培训的人员介入。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0118','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学告诉你，有人持续向她发送带有性暗示的信息，并在校园里尾随她。你该怎么帮她？','[\"劝她删掉消息，免得事情扩大\",\"陪她到安全地点，保存相关记录，并协助联系学院、学校受理渠道或警方\",\"在群里公开对方姓名和聊天截图\",\"让她独自约对方把话说清楚\"]',1,'先确保人身安全，再保留证据并求助；公开传播当事人信息可能造成二次伤害。遇到现实威胁应及时报警。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0119','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在校内目击暴力侵害，怎么做最合理？','[\"冲上去抓人\",\"先独自拍摄近景\",\"确保自己安全，立即向110或校园保卫部门求助并说明位置\",\"等事情结束再报告\"]',2,'人身安全优先，及时报警并提供清楚位置。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0120','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学连续几周被多人堵在宿舍门口辱骂、威胁，还被要求“不要告诉老师”。你应建议他怎么做？','[\"保存聊天和现场线索，告知辅导员或学院、学校保卫部门；有现实危险时报警\",\"继续忍耐，等对方自行停止\",\"约更多同学去堵对方\",\"把未经核实的个人信息发到公开平台\"]',0,'反复威胁不能当作普通玩笑；保留线索并向学校求助，紧急时报警，比私下对抗更安全。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0121','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','遭遇骚扰后，对方删除了聊天记录，但你仍有截图。下一步更合适的是？','[\"保存截图、时间地点等信息，向学校有关部门或警方求助\",\"删除所有证据\",\"继续单独赴约\",\"立即公开对方隐私报复\"]',0,'保留证据有助于核查，公开报复可能扩大伤害。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0122','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','大型活动散场时，出口突然拥挤。你应该怎么做？','[\"逆着人流快速返回\",\"推开前方人员抢先通过\",\"听从引导、保持重心、顺着人流缓慢移动，避免弯腰捡物\",\"停在出口中央等朋友\"]',2,'拥挤场景应避免逆行、推搡和突然停下。物品掉落时不要立即弯腰，以防跌倒和踩踏。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0123','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园公共区域发生人员争执并有升级趋势，你应该怎么做？','[\"靠近围观并拍摄\",\"保持安全距离，及时联系安保或报警，不参与、不围堵\",\"起哄刺激双方\",\"在网络直播具体位置\"]',1,'围观、起哄和传播现场位置可能扩大风险并妨碍处置。应优先远离危险、及时求助，并服从现场管理。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0124','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园讲座入口有人伪造“工作人员”身份引导排队改道，你会怎么做？','[\"自行组织逆行\",\"在群里传播未经证实的消息\",\"立即跟随\",\"向主办方或现场安保核实后再行动\"]',3,'大型活动应服从正式现场指引，异常情况及时核验。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0125','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园群出现“某楼发生重大事故”的模糊截图，你会怎么做？','[\"立即转发\",\"先核实官方信息，必要时向保卫处报告线索\",\"补充猜测细节\",\"在评论区公布疑似当事人姓名\"]',1,'未经核实的安全信息可能造成恐慌并侵害隐私。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0126','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你怀疑物品被盗，想让室友直接拷贝监控视频。合适做法是？','[\"公开要求保安发视频\",\"偷看监控室屏幕\",\"私自索取录像\",\"通过学校规定渠道报失并申请核查\"]',3,'监控涉及他人隐私，应按管理程序调取。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0127','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','音乐会入场时有人推搡并试图翻越护栏，怎么做更妥当？','[\"跟着翻\",\"远离拥挤点并告知现场工作人员\",\"推回去\",\"停在通道拍摄\"]',1,'大型活动应按分流路线入场，异常拥挤需现场处置。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0128','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','体育赛事散场后，你的同伴被人流挤散。你会怎么做？','[\"逆流寻找\",\"先随人流有序到安全区域，再联系约定地点\",\"站在出口中央等待\",\"翻越栏杆找人\"]',1,'逆行和停在出口会增加拥堵风险。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0129','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现校园照明灯底座松动，行人可能绊倒。你会怎么做？','[\"把问题发在娱乐群后离开\",\"用纸挡住\",\"自己拆掉灯\",\"提醒周边行人并向管理部门报修\"]',3,'设施隐患要及时报告，学生不宜擅自维修电气设备。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0130','治安安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','某“高薪兼职”要求你晚上独自到偏僻地点面试，并先缴纳服装费。正确做法是？','[\"机会难得，立即转账并前往\",\"不告诉任何人，以免被抢走机会\",\"把身份证原件交给对方保管\",\"核实招聘方资质，拒绝不合理收费，不独自前往可疑地点\"]',3,'正规招聘通常不会以入职、服装、押金等名义要求求职者先转账。面试前应核实信息，将行程告知亲友，并避免前往偏僻或不明场所。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0131','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新实验要使用以前没接触过的试剂，操作前该怎么处理？','[\"只看瓶身颜色\",\"让同学先试\",\"凭经验直接做\",\"查阅安全技术说明和实验室规程，接受指导\"]',3,'应了解危害、防护和应急措施后再操作。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0132','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验要用受控危险化学品，师兄说可从隔壁实验室借一瓶不登记。该怎么处理？','[\"只借半瓶\",\"把瓶签撕掉\",\"照做\",\"按学校采购、领用和登记制度办理\"]',3,'危险化学品的领用和流转必须可追溯。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0133','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','指导书要求常温操作，你想临时提高温度以缩短时间。该怎么处理？','[\"自行改参数\",\"先评估风险并取得指导教师或负责人同意\",\"只告诉同伴\",\"等实验后再汇报\"]',1,'改变温度可能改变反应速率、挥发性和压力风险。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0134','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','第一次进入设有射线装置的实验室，学长说“机器关着，先进去看看没事”。你会怎么做？','[\"先确认实验室准入要求和负责人许可，未获授权不进入操作区\",\"只要不碰机器就可以进入\",\"趁设备关闭拍照参观\",\"请学长替自己登记后进入\"]',0,'辐射场所的准入、培训与操作权限由管理制度确定，不能凭设备表面状态或他人口头保证判断安全。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0135','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','一项有明显危险源的实验计划在深夜独自进行。该怎么处理？','[\"独自完成更安静\",\"按实验室审批、值守和陪同要求调整安排\",\"只发朋友圈告知\",\"关闭监控减少干扰\"]',1,'危险实验应遵守准入和现场管理要求。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0136','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你未经培训就想操作高速离心机，该怎么处理？','[\"只选最低转速就不用培训\",\"按照网上视频自行尝试\",\"完成培训并取得授权后按规程使用\",\"让机器自动运行即可\"]',2,'高速设备涉及机械失衡和样本泄漏风险。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0137','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新生尚未完成实验室安全培训和准入考试，但想跟同学进入实验室“先看看”。正确做法是？','[\"有同学陪同就可以自行操作\",\"趁实验室人多时进入\",\"按实验室准入制度完成培训、考试和授权后再进入或操作\",\"只要不碰化学品就无需遵守准入要求\"]',2,'南开大学实验室安全管理要求落实安全教育和准入制度。未经培训、考核和授权的人员不应擅自进入受控区域或操作设备。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0138','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','正在进行需要加热的危险化学实验，操作者想离开十分钟取快递。正确做法是？','[\"调低温度后直接离开\",\"请不熟悉实验的同学随便看一下\",\"不擅自离岗；按规程停止或交由具备资格的人员监护后再离开\",\"锁上实验室门即可\"]',2,'实验过程中不得擅自离岗，特别是涉及危险化学品、高温、高压等操作。离开前必须按规程停止实验或安排合格人员监护。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0139','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','进入实验室发现自己的护目镜镜片破裂，正确做法是？','[\"更换合格护目镜后操作\",\"戴普通太阳镜\",\"不戴眼部防护\",\"凑合戴\"]',0,'破损护目镜不能有效防护飞溅。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0140','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','戴着可能沾有化学品的手套操作手机，主要问题是？','[\"可能把污染物带到个人物品和公共表面\",\"手套会变松\",\"不会有问题\",\"手机会没电\"]',0,'受污染手套不应接触个人物品，离开操作区前要按规程脱除。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0141','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','完成实验后没有看到明显污染，可以直接拿食物吃吗？','[\"可以\",\"应脱下防护用品并规范洗手后再进食\",\"只擦手套即可\",\"用实验室水槽洗水果\"]',1,'污染可能不可见，实验室内也不应进食。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0142','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学想把奶茶放在实验台角落，理由是“离试剂很远”。该怎么处理？','[\"只放冷饮\",\"同意\",\"提醒实验室禁止饮食，移至指定区域\",\"盖上杯盖即可\"]',2,'实验环境可能存在不可见污染，饮食应远离实验区。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0143','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','进行有化学飞溅风险的实验时，哪种着装更合适？','[\"按风险要求穿实验服、护目镜、长裤和包覆脚面的鞋\",\"穿拖鞋便于冲洗\",\"只戴普通近视眼镜\",\"戴耳机避免噪声干扰\"]',0,'实验人员应根据风险正确使用实验服、护目镜、手套等防护用品。普通眼镜不能代替专业护目镜，拖鞋会增加暴露风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0144','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验结束时发现同伴留下不明试剂容器，你会怎么做？','[\"带回宿舍\",\"倒掉\",\"保持原状并联系责任人核实\",\"闻一下判断\"]',2,'不明化学品不能擅自识别或处置，应交由责任人确认。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0145','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','想用饮料瓶装少量试剂带回办公室，正确选择是？','[\"使用符合要求并有标签的专用容器，按规定存放\",\"用水瓶但贴昵称\",\"放入书包\",\"饮料瓶方便\"]',0,'食品容器易引发误饮和识别错误。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0146','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','想确认一瓶试剂是否有刺激性气味，正确方式是？','[\"把鼻子贴瓶口闻\",\"不凭气味辨认，按标签和安全资料核实\",\"让同学先闻\",\"加热后闻\"]',1,'直接闻未知试剂可能吸入有害蒸气。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0147','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人把个人午餐放进存放实验试剂的冰箱，正确做法是？','[\"立即移走并遵守实验室食品与试剂分离要求\",\"包两层保鲜膜即可\",\"放在冰箱门上\",\"分层即可\"]',0,'食品与实验物品混放存在污染风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0148','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','使用易燃溶剂附近有人计划用明火加热，应该怎么做？','[\"继续操作\",\"停止并按实验方案选择安全热源、保持与火源隔离\",\"用纸挡住火苗\",\"开香薰掩盖味道\"]',1,'易燃蒸气接触火源可能起火，热源选择须符合规程。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0149','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','冰箱中一管样品标签只写“我的”，你会怎么做？','[\"给样品加热辨认\",\"随手放回任意位置\",\"猜成分继续用\",\"按实验室标识和交接规定核实后处理\"]',3,'样品名称、危险性和责任人不清会妨碍安全使用与应急处置。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0150','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验台上有一瓶标签脱落、成分不明的液体。你会怎么做？','[\"打开闻气味判断\",\"少量混入其他废液桶测试\",\"直接倒入下水道\",\"停止使用并隔离，联系实验室负责人按规定确认和处置\"]',3,'未知化学品可能有毒、易燃或发生不相容反应。不能闻、尝、混合或随意倾倒，应隔离并由负责人按照制度处理。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0151','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','两种化学品的性质和灭火方法相互抵触，应如何存放？','[\"放在同一个柜子便于管理\",\"根据性质分类、分开存放并清晰标识\",\"混合后减少占用空间\",\"打开瓶盖释放压力\"]',1,'性质不相容的化学品混放可能导致反应、燃烧或爆炸，应分类、分区存放并保持标识完整。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0152','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','需要把高压气瓶搬到另一房间，该怎么处理？','[\"在地上滚动\",\"由受训人员按规程使用合适推车并固定\",\"抱在怀里\",\"拽着阀门走\"]',1,'气瓶跌倒和阀门受损可能造成严重事故。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0153','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学准备在密闭小房间大量使用液氮，主要应警惕什么？','[\"手套变色\",\"光线太亮\",\"氧气被置换造成缺氧风险\",\"网络中断\"]',2,'低温液体蒸发会占用空气体积，操作需符合通风和防护要求。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0154','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','使用液氮时穿普通薄棉手套，正确判断是？','[\"只要动作快就安全\",\"足够安全\",\"应按规程使用适合低温操作的防护用品\",\"不戴手套更灵活\"]',2,'极低温可能造成冻伤，防护用品需与危险相匹配。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0155','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验室高压气瓶正确的放置方式是？','[\"横放在地面，方便滚动\",\"直立并可靠固定，远离热源和强烈振动\",\"放在阳光直射的窗边\",\"把不同性质气体随意集中堆放\"]',1,'高压气瓶应分类管理、直立固定，远离热源、曝晒和强烈振动，防止倾倒、阀门损坏或发生泄漏。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0156','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','加热密闭玻璃容器里的液体，最需警惕的是？','[\"压力上升导致容器破裂\",\"液体升温比敞口容器慢\",\"玻璃透明，容易忽略液体颜色变化\",\"容器贴了标签后不便观察温度\"]',0,'密闭容器受热可能迅速增压，未经批准不得这样加热。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0157','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','烧杯边缘出现裂纹，但容量够用。该怎么处理？','[\"用胶带贴住\",\"只盛冷水\",\"继续加热\",\"停止使用并按破损玻璃器皿流程处理\"]',3,'裂纹会增加割伤和加热破裂风险。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0158','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','刚从烘箱取出的容器外观与常温相同，正确做法是？','[\"直接用手拿\",\"使用合适耐热防护和工具，并作高温提醒\",\"交给不知道的人拿\",\"放在纸上降温\"]',1,'高温物品外观不一定明显，接触可能烫伤。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0159','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','高压灭菌设备运行结束，尚未确认压力归零，有人想立即开门。该怎么处理？','[\"用力撬门\",\"先泼冷水\",\"立即开\",\"按设备规程确认安全状态后由受训人员操作\"]',3,'残余压力和高温蒸汽可能造成严重烫伤。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0160','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','通风橱风量报警，实验正要产生刺激性蒸气。该怎么处理？','[\"继续操作\",\"暂停实验并报告设备故障，待确认安全后再进行\",\"用口罩代替\",\"打开门窗即可\"]',1,'工程防护失效时不能把个人防护当作完全替代。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0161','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','废液桶没有成分标签，下一位同学准备倒入溶剂。该怎么处理？','[\"摇匀再倒\",\"直接倒\",\"停止投放并请责任人确认成分和分类\",\"先闻桶口\"]',2,'混合不相容废液可能发生反应，标签和分类必须明确。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0162','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','进入新实验室前，除了实验台位置，还应先确认什么？','[\"窗帘颜色\",\"同学座位\",\"饮水机品牌\",\"洗眼器、喷淋、报警和疏散出口位置\"]',3,'熟悉应急设施位置可缩短事故处置时间。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0163','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','做完实验想把少量未知废液倒进水槽，应该怎么做？','[\"只在晚上倒\",\"加洗洁精后倒\",\"水冲久一点就行\",\"暂停并按实验室废弃物分类规定处置\"]',3,'实验废液可能具有毒性、腐蚀性或环境危害，不能随意排放。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0164','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','需要把实验用生物样本送到另一楼宇，应该怎么做？','[\"请外卖骑手送\",\"装普通塑料袋手提\",\"按实验室要求使用合适容器和交接流程\",\"放进饮料杯\"]',2,'样本运输需防泄漏并保持交接可追溯。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0165','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验后的一次性针头该怎么处理？','[\"放入指定锐器容器\",\"用手掰弯后丢弃\",\"暂放在桌边\",\"直接扔普通垃圾桶\"]',0,'锐器需按规范收集，避免刺伤和潜在污染。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0166','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验中有少量溶剂洒在台面上，暂时无人受伤。学生首先应怎么做？','[\"用纸巾擦净后继续实验\",\"先闻一闻确认是不是易燃溶剂\",\"停止操作，避开洒漏处并报告实验教师，按该实验室预案处理\",\"打开附近电器加快空气流动\"]',2,'不明溶剂可能易燃、有毒或有刺激性；学生不应凭“量少”自行擦拭。通风、隔离和清理方式应由教师按物质性质与预案决定。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0167','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验室出现不明刺鼻气味，有同学出现头晕，该怎么处理？','[\"打开香水掩盖\",\"独自靠近闻\",\"继续确认气味来源\",\"立即撤离并报告，避免再次进入\"]',3,'未知气体可能危及呼吸，应优先撤离和求援。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0168','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验用生物样本容器摔裂，液体洒在地面。未经专门培训的学生该怎么处理？','[\"立即用普通拖把擦净\",\"把碎片徒手捡起\",\"提醒周围人员避让并报告实验教师，按实验室生物安全预案处置\",\"开门让同学进来帮忙\"]',2,'样本性质不同，暴露和扩散风险也不同。先限制接触、报告负责人，由受训人员按预案处理，不能自行清扫。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0169','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','皮肤接触不明腐蚀性液体，第一步该做什么？','[\"涂护手霜\",\"等疼痛再处理\",\"自行加酸碱中和\",\"按现场应急规程立即用大量流动水冲洗并求医、报告\"]',3,'应尽快去除污染，不能盲目使用化学品中和。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0170','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新入实验室不知道紧急断电位置，正确做法是？','[\"操作前询问并熟悉位置与使用条件\",\"自己试拉所有开关\",\"只记住普通插座\",\"用到时再找\"]',0,'熟悉应急设施有助于快速控制事故。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0171','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实验产生的有机溶剂废液应该如何处理？','[\"按类别装入相容容器，规范标识并交由规定渠道处置\",\"倒入下水道并大量冲水\",\"与生活垃圾混合丢弃\",\"与未使用试剂混放节省空间\"]',0,'实验废弃物不得倒入下水道或混入生活垃圾，应分类存放、包装和标识，并由有资质的渠道处置。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0172','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','化学品意外溅入眼睛，现场设有洗眼器。第一步该怎么做？','[\"闭眼等待疼痛缓解\",\"用纸巾反复擦拭眼球\",\"自行滴眼药水后继续实验\",\"立即使用洗眼器持续充分冲洗并呼叫同伴，按应急流程就医\"]',3,'应立即、持续、充分冲洗，尽快去除污染物，并同步求助和就医。不能因自行判断伤情较轻而延误处理。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0173','实验室安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现实验室安全隐患后，最完整的处理链条是？','[\"报告、记录、落实整改并复核结果\",\"只贴警示纸\",\"等学期末统一解决\",\"在群里抱怨即可\"]',0,'隐患应明确责任和整改结果，避免问题反复出现。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0174','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','学校邮箱提示陌生设备登录，最合适的处理是？','[\"忽略\",\"从官方入口改密、退出其他会话并联系信息部门\",\"把提醒转给所有人\",\"只删邮件\"]',1,'异常登录可能意味着账号泄露，应及时控制访问。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0175','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','开启邮箱双因素认证的主要作用是？','[\"自动删除垃圾邮件\",\"让邮件更漂亮\",\"密码泄露时增加一道身份核验\",\"使附件变大\"]',2,'额外验证有助于阻止仅掌握密码的人登录。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0176','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团为方便管理，十个人共用一个学校邮箱账号，主要风险是？','[\"邮箱容量变大\",\"邮件数量减少\",\"难以追踪操作，密码泄露后影响面扩大\",\"网络速度变慢\"]',2,'多人共用账号削弱权限控制和责任追溯。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0177','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','登录着校园系统的手机丢失，应优先？','[\"只发寻物启事\",\"让朋友试登录\",\"等捡到再说\",\"远程锁定或退出会话、改密并按校内渠道报失\"]',3,'应尽快减少账号和个人信息暴露。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0178','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','毕业前发现多个陌生应用仍有学校账号授权，应该怎么做？','[\"只删桌面图标\",\"保持不变\",\"通过官方账号设置取消不再需要的授权\",\"把密码发给应用客服\"]',2,'收回不必要授权可减少信息暴露。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0179','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','给社团平台设置密码，哪种方案较好？','[\"与个人邮箱相同\",\"使用独立的高强度密码并妥善保存\",\"写在公开群公告里\",\"12345678\"]',1,'独立密码可减少一个平台泄露后连锁失守。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0180','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','没有登录操作却收到学校账号验证码，该怎么处理？','[\"点击短信里的任何链接\",\"把验证码发给来电“客服”\",\"忽略索取验证码的人，检查账号安全并从官方入口改密\",\"在群里公布验证码\"]',2,'异常验证码可能意味着他人尝试登录，验证码不能交给别人。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0181','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在实验室电脑上离开座位几分钟，该怎么处理？','[\"锁屏并保管账号凭据\",\"让隔壁同学看着\",\"只关显示器\",\"保持系统解锁\"]',0,'短时离开也可能使他人访问个人账号和数据。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0182','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团管理员毕业离校，账号仍保留管理权限。该怎么处理？','[\"把密码贴在群公告\",\"直接删除所有历史文件\",\"继续保留\",\"按社团和平台流程移交并撤销旧权限\"]',3,'权限应随职责变化及时调整。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0183','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在借用电脑上点击“永久保存学校账号密码”，风险是什么？','[\"只影响字体\",\"无法再修改密码\",\"使网页变慢\",\"后续使用者可能直接访问你的账号\"]',3,'共享设备不应保存个人账号凭据。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0184','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','平台显示你的账号仍登录在旧手机上，该怎么处理？','[\"把旧手机序列号发群里\",\"只删除新手机应用\",\"忽略\",\"在官方设置中注销旧设备会话\"]',3,'清除不再使用的会话可减少未授权访问。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0185','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','为了方便记忆，同学把统一身份认证、邮箱和购物网站密码设为相同。主要风险是什么？','[\"密码更容易自动更新\",\"只会影响购物网站\",\"任一平台泄露都可能导致其他账号被“撞库”登录\",\"只要密码超过六位就没有风险\"]',2,'重复使用密码会放大单个平台泄露的影响。重要账号应使用不同的高强度密码，并开启多因素认证。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0186','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','群里有人发来二维码，称“扫码即可查看获奖名单”。扫码后手机提示授权电脑登录账号，你会怎么做？','[\"立即确认登录\",\"把确认页面截图发给对方\",\"输入短信验证码帮助对方登录\",\"先确认二维码来源和登录设备，不明请求直接取消\"]',3,'扫码可能触发账号登录授权，而不是打开普通网页。应核对来源、设备和授权内容，任何非本人发起的登录都应取消。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0187','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“教务处通知”邮件的显示名正常，但发件域名多了一个字母，该怎么处理？','[\"回复身份证号确认\",\"先下载附件\",\"只看显示名\",\"不要点击链接，独立登录官方系统核实\"]',3,'显示名称可伪造，仿冒域名是钓鱼邮件常见手法。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0188','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','群里“成绩查询”短链接看不到真实地址，正确做法是？','[\"从学校官方入口独立访问成绩系统\",\"先转给室友试\",\"输入密码看看\",\"立即点开\"]',0,'短链接可能隐藏钓鱼站点。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0189','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','邮件标题为“导师紧急修改”，附件是可执行程序而不是文档。该怎么处理？','[\"立即运行\",\"通过原有联系方式向导师核实，勿运行附件\",\"转给同学运行\",\"关闭安全软件再运行\"]',1,'冒充熟人的附件可能携带恶意程序。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0190','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','浏览学校网站时突然弹出“系统管理员远程协助”窗口并索要密码，该怎么处理？','[\"下载弹窗软件\",\"输入密码\",\"关闭页面并通过学校官方支持渠道核实\",\"共享屏幕\"]',2,'弹窗中的身份声明不能证明其真实可信。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0191','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','搜索学校客户端时，排在首位的是广告下载站。正确做法是？','[\"看到第一条就下载\",\"核对官方域名并从学校正式页面获取软件\",\"下载多个版本试用\",\"关闭浏览器提示\"]',1,'搜索排序和广告不能证明软件来源可信。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0192','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','群文件名为“奖学金名单”，下载后要求启用宏。该怎么处理？','[\"先关闭杀毒软件\",\"立即启用\",\"停止操作并向发布者通过独立渠道核实\",\"转给所有班级\"]',2,'异常宏请求可能用于执行恶意代码。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0193','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','一封邮件附有南开校徽，但正文要求把账号密码回复到私人邮箱。你会怎么做？','[\"先让同学试\",\"相信校徽\",\"不回复，向学校官方渠道核实\",\"只回复密码\"]',2,'校徽图片容易复制，索要口令是明显风险信号。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0194','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','邮件称校园账号将在两小时后停用，要求点击链接重新验证。最可靠的核实方式是？','[\"从学校官网或已保存的官方入口登录，并联系网信部门核实\",\"直接点击邮件中的链接\",\"回复邮件询问发件人\",\"把邮件转发给更多同学试用\"]',0,'钓鱼邮件常利用“限时停用”制造紧迫感。应绕开邮件中的链接，通过官方入口和官方联系方式核实。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0195','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','收到群友发来的“校园VPN破解版”安装包，正确做法是？','[\"从学校或软件官方渠道获取客户端，不安装来源不明的软件\",\"关闭安全软件后安装\",\"先让同学安装测试\",\"只要文件名正确就可以运行\"]',0,'来源不明的软件可能包含恶意程序。校园服务客户端应从学校或软件官方渠道下载，不能用文件名或他人试用代替安全核验。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0196','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','一个课表小程序要求访问通讯录和精确位置，你会怎么做？','[\"全选同意\",\"检查权限必要性，拒绝与功能无关的授权\",\"把室友手机一起授权\",\"卸载学校官方课表\"]',1,'个人信息授权应遵循最小必要原则。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0197','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','分享含全班手机号的表格时，哪项设置更安全？','[\"仅授权需要的人查看，并按需要隐藏无关字段\",\"发公开社交平台\",\"取消访问日志\",\"任何人持链接可编辑\"]',0,'最小范围共享可减少信息泄露。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0198','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','毕设数据只保存在一台个人笔记本中，较稳妥的是？','[\"只靠自动保存\",\"按导师和学校要求建立受控备份并验证可恢复\",\"发到公开群备份\",\"复制到陌生网盘\"]',1,'单点存储有丢失风险，科研数据还需注意访问权限。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0199','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','免费浏览器插件要求读取所有网页内容和剪贴板，应该怎么做？','[\"装在公共电脑就安全\",\"安装后把密码存在网页里\",\"直接装\",\"核实来源、权限和必要性，不明插件不安装\"]',3,'过宽权限可能让插件接触账号和敏感数据。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0200','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在线会议含未公开科研数据，有人打算把录屏公开上传。该怎么处理？','[\"先确认参会者授权和数据发布权限\",\"只删会议标题\",\"用匿名账号发布\",\"立即上传\"]',0,'公开录屏可能泄露个人信息和科研资料。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0201','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','食堂桌面原有付款码被贴上一张新码，收款方名称异常。你会怎么做？','[\"照样支付\",\"暂停支付并让工作人员核实收款码\",\"把码撕掉带走\",\"用室友手机付款\"]',1,'实体二维码可能被替换，付款前需核对收款对象。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0202','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','上传活动照片前，为什么要检查位置信息和相册元数据？','[\"可能暴露行程和地点\",\"会使照片变黑\",\"影响点赞数\",\"会改变画质\"]',0,'照片附带的位置及时间信息可能泄露个人轨迹。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0203','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','交作业时将含身份证号的文件放在“任何人可查看”网盘链接中，该怎么处理？','[\"把链接再分享出去\",\"只缩短文件名\",\"保持公开\",\"收紧权限并删除不必要敏感字段\"]',3,'共享范围应与作业目的相匹配。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0204','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','使用公开AI工具整理资料时，哪种做法较安全？','[\"让工具代填他人信息\",\"上传完整学生名单\",\"先去除不必要的个人信息，并遵守学校数据使用要求\",\"上传未公开账号密码\"]',2,'外部服务的数据处理方式未必适合敏感资料。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0205','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','看到未经证实的“宿舍停水三天”群消息，该怎么处理？','[\"查看学校正式通知或联系后勤核实\",\"改写得更夸张\",\"附上室友电话\",\"立即转发\"]',0,'校园公共信息应核实来源后传播。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0206','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','含有实验数据的U盘遗失，该怎么处理？','[\"当作普通失物\",\"及时告知导师和学校信息管理人员，评估数据泄露风险\",\"只在群里求助\",\"等别人拾到\"]',1,'除找回设备外，还需评估文件内容和访问风险。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0207','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','向客服反馈登录问题时，截图露出了完整验证码和学号。该怎么处理？','[\"遮盖无关敏感信息后走官方反馈渠道\",\"把图片转成PDF就安全\",\"只改文件名\",\"原图发公开群\"]',0,'截图同样可能泄露可用于身份验证的信息。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0208','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在自助打印店打印含身份证号的报名材料，完成后该怎么处理？','[\"取走纸张、退出账号并清理打印任务记录\",\"让店主保存电子版\",\"把多余纸张留在机器旁\",\"直接离开\"]',0,'打印流程的纸质和电子残留都可能泄露信息。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0209','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','送修存有科研数据的电脑，该怎么处理？','[\"直接交出所有账号密码\",\"按学校和导师要求备份、退出账号并处理敏感数据\",\"让维修店随意复制\",\"只关机\"]',1,'维修前应降低数据和账号暴露范围。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0210','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团做问卷，只统计专业年级，却要求填写身份证号和家庭住址。该怎么处理？','[\"让所有同学填虚假信息\",\"公开问卷结果\",\"都填写\",\"建议删减无关字段并说明信息用途\"]',3,'收集个人信息应与目的相匹配，避免过度收集。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0211','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在公共电脑登录学校邮箱后，离开前怎么做最稳妥？','[\"只关闭显示器\",\"正常退出账号，清除必要的登录状态，并确认没有保存密码或下载敏感文件\",\"只关闭浏览器窗口\",\"把密码保存在浏览器中方便下次使用\"]',1,'仅关闭窗口可能保留登录会话。使用公共设备后应退出账号、避免保存密码，并妥善删除临时下载的敏感文件。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0212','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在教学楼捡到一个标有“考试资料”的U盘，正确做法是？','[\"插入个人电脑查看失主信息\",\"在实验室电脑上打开\",\"不接入设备，交给管理人员或学校相关部门处理\",\"复制文件后在群里分享\"]',2,'来源不明的移动存储设备可能携带恶意程序。不要因文件名具有吸引力而接入个人或学校设备，应交由适当人员处理。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0213','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','准备在社交平台发布假期照片时，哪种做法更安全？','[\"同时公开宿舍号、行程和返校时间\",\"减少实时位置、证件和详细行程暴露，返程后再选择性发布\",\"上传校园卡和车票照片\",\"把账号设置为公开以便失物招领\"]',1,'实时位置、长期离寝信息和证件内容可能被用于跟踪、盗窃或身份冒用。发布前应检查背景和图片中的敏感信息。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0214','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电脑反复提示安装安全更新，但你担心影响使用。该怎么处理？','[\"只改壁纸\",\"永久关闭更新\",\"通过官方渠道安排更新并保存工作\",\"下载陌生“免更新补丁”\"]',2,'安全更新用于修复已知漏洞。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0215','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','公共Wi\\-Fi名称与学校网络很像，却要求安装陌生证书。你会怎么做？','[\"让同学先试\",\"关闭杀毒软件\",\"立即安装\",\"向学校网信部门核实，避免在未确认网络上登录敏感系统\"]',3,'仿冒网络和异常证书要求可能用于窃取信息。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0216','网络安全','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','连接来源不明的免费Wi\\-Fi后，哪项做法更安全？','[\"登录网银转账\",\"输入统一身份认证密码\",\"关闭手机锁屏密码\",\"避免进行支付和重要账号登录，必要时切换可信网络\"]',3,'来源不明的公共网络可能存在监听、仿冒热点等风险。在不可信网络中应避免支付和重要账号登录。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0217','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','兼职群让你完成点赞任务，前两次确实返还了小额佣金，随后要求充值5000元做“联单”。你会怎么做？','[\"前面能提现，说明平台可靠\",\"只做这一次大额任务\",\"立即停止参与，不再转账并保留证据\",\"借钱完成联单后再退出\"]',2,'小额返利是常见的“养信”手段，后续会以联单、卡单、解冻等理由诱导不断充值。凡是要求垫资刷单、充值做任务的，都应高度警惕。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0218','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','刷单平台称你因“操作错误”导致账户冻结，必须再转一笔钱才能连同本金提现。正确判断是？','[\"补一笔就能全部取回\",\"只要签电子合同就安全\",\"找同学共同充值可以分担风险\",\"这是常见的继续诈骗话术，不应再转账\"]',3,'“操作错误、卡单、账户冻结、补足流水”都是刷单诈骗常用借口。继续付款通常只会扩大损失。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0219','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“兼职”让你用自己的收款码代收陌生人的钱，再转给指定账户赚佣金。该怎么处理？','[\"拒绝并警惕涉诈资金流转风险\",\"先做一单\",\"让室友提供收款码\",\"接受\"]',0,'代收代转可能帮助转移非法资金。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0220','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','对方称只要把银行卡和手机卡借给他“做任务流水”，每天可获得报酬。你会怎么做？','[\"不提供，并警惕自己成为电诈“工具人”\",\"只借一天没有关系\",\"只提供银行卡密码，不提供验证码\",\"让对方签收条后再借\"]',0,'出借、出租、出售银行卡、电话卡可能被用于转移涉诈资金，既会造成账户风险，也可能承担法律责任。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0221','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人出高价借你的实名电话卡“做营销测试”。该怎么处理？','[\"出租\",\"拒绝并保护实名卡信息\",\"只借一天\",\"请同学开卡再借\"]',1,'非法出租、出借电话卡可能被用于诈骗等违法活动。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0222','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','兼职平台收购已实名的社交账号，说“只用于引流”。该怎么处理？','[\"只卖小号\",\"出售\",\"拒绝，实名账号不能随意买卖、出借\",\"先解绑邮箱再卖\"]',2,'实名账号可能被用于诈骗，法律禁止非法买卖和出租出借。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0223','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“财务实习”要求你把个人银行卡交公司刷流水，承诺每天给报酬。该怎么处理？','[\"只给卡号\",\"让家人代办\",\"交卡\",\"拒绝并核实招聘单位，必要时举报\"]',3,'银行卡不得出借用于不明交易，可能涉及犯罪资金。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0224','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社交平台上的“投资导师”展示连续盈利截图，并要求你下载其发送的App跟单。正确做法是？','[\"先投少量资金试试\",\"不下载不明投资App，通过持牌机构和官方渠道核实\",\"相信群内其他学员的盈利截图\",\"把全部生活费投入以获取高收益\"]',1,'虚假投资平台可操控后台数据和盈利截图，甚至允许前期小额提现。投资应通过合法持牌机构，不能相信“稳赚不赔”“内幕消息”。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0225','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','投资平台显示账户盈利10万元，但客服要求先缴2万元“个人所得税”才能提现。应该怎么做？','[\"缴税后提现\",\"再投资一次抵扣税费\",\"停止转账，保留证据并向警方或有关部门咨询\",\"把账号交给客服代操作\"]',2,'诈骗平台常以税费、保证金、解冻费等名义阻止提现并继续骗钱。正规税费不会由陌生客服要求转入个人或不明账户。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0226','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','网恋对象称自己掌握某平台漏洞，催你一起投资，并远程指导操作。最大的风险信号是？','[\"对方每天聊天很有耐心\",\"平台界面制作精美\",\"对方发来身份证照片\",\"对方把感情关系与高收益投资绑定，并催促向指定平台转账\"]',3,'诈骗分子可能长期经营感情，再诱导投资虚假平台。照片、证件和聊天记录都可能伪造，感情信任不能替代金融资质核验。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0227','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你在社交软件上认识一个“学长”，聊得很投机。对方说发现一个“稳赚不赔”的投资平台，带你一起赚钱，你会怎么做？','[\"先投500试试，亏了就当交朋友\",\"拒绝投资，并意识到可能是“杀猪盘”\",\"让对方先投，跟着他操作\",\"告诉室友，拉室友一起投\"]',1,'“稳赚不赔”和陌生人推荐投资平台都是明显的诈骗风险信号。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0228','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】网恋对象带你赚钱，只要第一次能提现成功，就可以加大投入。','[\"正确\",\"错误\"]',1,'诈骗平台可能先允许小额提现，以诱导后续大额投入。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0229','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','仅在网上认识两周的“恋人”称家人重病，连续请求你转账。正确做法是？','[\"感情需要信任，立即转账\",\"让对方写借条就安全\",\"使用网贷帮助对方\",\"拒绝继续转账，核实身份和事实，必要时向亲友或警方求助\"]',3,'婚恋诈骗常以疾病、事故、周转等理由逐步索款。线上人设、照片、视频甚至证件都可能伪造，应保持独立核验和财务边界。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0230','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','网友自称军人或涉密单位人员，长期拒绝视频，却不断发送制服照并请求代为投资。你会怎么做？','[\"警惕虚假人设，不代为投资、不转账，并核实身份\",\"涉密人员不能视频很正常\",\"对方身份特殊，更值得信任\",\"先小额投资测试平台\"]',0,'诈骗分子常用军人、工程师、海外人士等人设解释无法见面，并进一步诱导投资或汇款。身份故事不能替代可靠核验。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0231','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','网恋对象让你登录其投资账户代操作，账户不断盈利，随后邀请你自己充值。这个过程的目的可能是？','[\"教你免费理财\",\"用可操控的虚假盈利培养信任，再诱导大额投入\",\"帮你提高计算机技能\",\"测试你的感情忠诚度\"]',1,'所谓账户余额和收益可能由后台伪造，代操作是常见的信任铺垫。不要向对方指定的平台充值。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0232','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你在社交软件上认识一个“美女”，对方主动邀请你视频“坦诚相见”，你会怎么做？','[\"反正就两个人，不会有事\",\"先视频看看，如果是假的就挂断\",\"让对方先脱，自己再看看\",\"拒绝并拉黑，这很可能是裸聊敲诈\"]',3,'对方可能录屏后实施敲诈，不要开始视频或发送私密影像。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0233','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是“杀猪盘”的特征？','[\"对方照片异常帅气／漂亮，并且性格、爱好等完美符合你的择偶标准\",\"聊几天就确立恋爱关系\",\"声称有“内部渠道”“稳赚不赔”\",\"让你下载不明App或点击陌生链接投资\"]',0,'这类诈骗常先建立亲密关系，再以投资赚钱为由诱导转账。','approved','2026-10-17 09:49:41','[0,1,2,3]'),('UPLOAD-1792230579860-0234','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】下载了对方发的App但没注册成功，就不会有风险。','[\"正确\",\"错误\"]',1,'来历不明的App即使未注册，也可能索取权限或收集个人信息。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0235','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】如果不幸陷入裸聊敲诈，对方威胁要群发视频，以下哪些做法是正确的？','[\"立刻转账，破财消灾\",\"不转账，保存证据，立即报警\",\"和对方讨价还价，争取少转点\",\"告诉家人朋友，寻求帮助\"]',1,'转账不能保证对方删除影像。应保存证据，及时报警并寻求支持。','approved','2026-10-17 09:49:41','[1,3]'),('UPLOAD-1792230579860-0236','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','自称平台客服的人说你开通了“百万保障”，不取消每月会扣费，并要求共享屏幕。你会怎么做？','[\"按客服要求共享屏幕\",\"告诉对方银行卡余额\",\"下载对方指定的会议软件\",\"挂断电话，通过平台官方App或客服电话核实\"]',3,'“百万保障自动扣费”是常见诈骗话术。共享屏幕可能泄露验证码、账户和支付信息，应通过官方渠道独立核实。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0237','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“快递客服”准确说出你的姓名和订单，并称包裹丢失，需要银行卡号和短信验证码理赔。正确做法是？','[\"不提供敏感信息，通过购物平台订单页联系官方客服\",\"信息准确，说明对方可信\",\"只提供验证码，不提供密码\",\"按对方要求开通贷款账户接收赔款\"]',0,'诈骗分子可能通过非法渠道获取订单信息。正规退款通常按原支付路径退回，不需要索取短信验证码或要求贷款、转账。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0238','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','快递包裹中有一张“扫码领取20元红包”的卡片，扫码后要求下载陌生App。你会怎么做？','[\"金额不大，可以试试\",\"不扫码、不下载，必要时通过商家或平台官方渠道核实\",\"用同学手机扫码更安全\",\"先填写身份证号再判断\"]',1,'快递卡片可能被用于引流刷单、盗取信息或传播恶意软件。不要因小额礼品放松警惕。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0239','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','陌生人称培训机构倒闭，拉你进“退款群”并让购买理财产品。该怎么处理？','[\"购买\",\"通过机构或监管部门正式渠道核实退款，不参与投资\",\"只投小额\",\"让同学先试\"]',1,'以退款为入口诱导投资或充值是常见变形骗局。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0240','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','快递员称送错地址，让你先垫付“转运费”才重派。该怎么处理？','[\"转给个人账户\",\"通过快递公司或购物平台官方渠道核实\",\"先交半价\",\"把验证码发给快递员\"]',1,'物流服务费应在可信订单渠道核实，避免私下转账。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0241','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是快递诈骗的典型套路？','[\"主动来电说快递丢失要赔偿\",\"要求你扫码填写银行卡信息\",\"要求你提供手机收到的验证码\",\"官方App内，官方客服发送的信息\"]',0,'冒充快递员或客服，以赔偿为名套取银行卡信息、验证码，是常见套路。','approved','2026-10-17 09:49:41','[0,1,2]'),('UPLOAD-1792230579860-0242','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你接到“快递员”电话，说你的快递丢失，要进行双倍赔偿，让你加微信并提供银行卡号和验证码，你会怎么做？','[\"加微信，提供信息等着收钱\",\"提供验证码，反正有短信提示\",\"告诉对方银行卡号，但不给密码应该没事\",\"挂断电话，通过快递官方App查询物流状态\"]',3,'应自行打开官方渠道核实，不能向来电者提供验证码。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579860-0243','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】只要对方能准确说出你的姓名、电话和购买的商品，就一定是真的客服。','[\"正确\",\"错误\"]',1,'订单和个人信息可能泄露，知道这些信息不能证明对方身份。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0244','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人在社交平台出售“内部低价票”，要求脱离平台私下转账。你会怎么做？','[\"通过正规售票平台交易，不私下转账\",\"对方票价低，马上付款\",\"要求对方发身份证后付款\",\"先付全款再线下取票\"]',0,'稀缺票务常被用于诱导私下交易。身份证照片、订单截图和电子票截图都可能伪造，应使用正规渠道和平台保障机制。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579860-0245','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你向个人代购买商品后，对方连续要求补缴“关税、保证金、认证费”。正确做法是？','[\"为避免损失继续补款\",\"停止转账，通过正规平台核实并保留聊天、付款记录\",\"再购买一件商品抵扣费用\",\"把银行卡交给对方自动扣款\"]',1,'付款后不断追加费用是虚假购物服务诈骗的典型特征。应停止继续付款，保存证据并通过平台投诉或报警。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579860-0246','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','二手交易买家发来“已付款”截图，并让你扫码进入所谓客服页面解冻收款。你会怎么做？','[\"相信付款截图\",\"扫码并填写银行卡验证码\",\"只以正规交易平台或本人账户的实际到账状态为准\",\"先支付解冻费再发货\"]',2,'付款截图可以伪造，收款一般不需要卖家缴纳解冻费。应在正规平台核对订单和到账，不点击买家提供的客服链接。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579860-0247','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','学生群有人售演唱会“内部票”，要求先转账到个人账户锁票。该怎么处理？','[\"只付订金\",\"让他发身份证照片即可\",\"付款\",\"通过正规票务平台核验并交易\"]',3,'虚假票务常借稀缺性和紧迫感诱导私下付款。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579861-0248','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','票务卖家提供二维码截图和订单截图，却拒绝在平台内交易。你会怎么做？','[\"停止私下交易，使用支持核验与保障的渠道\",\"先把钱转过去\",\"请卖家口头保证\",\"截图足够可信\"]',0,'票据与订单截图可伪造或重复售卖。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579861-0249','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','校园二手群里有人以极低价卖一批教材，但要求平台外先付款。该怎么处理？','[\"先付邮费\",\"让卖家发模糊照片\",\"立即付款\",\"优先当面验物或通过有保障的平台交易\"]',3,'明显低价和脱离平台交易增加货不对板或收款消失风险。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579861-0250','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','活动结束后陌生账号说你中了电脑，但需要先交“公证费”。该怎么处理？','[\"请朋友代交\",\"付款\",\"向活动主办方官方渠道核实，不预付不明费用\",\"先填银行卡密码\"]',2,'领奖前置费用与陌生收款账户是常见风险信号。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579861-0251','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','买二手物品时，卖家发来与平台相似的付款页，地址拼写多了一个字母。该怎么处理？','[\"只付订金\",\"换浏览器支付\",\"继续付款\",\"关闭页面，仅通过正规平台App内订单支付\"]',3,'高仿网址可能窃取账户和资金。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579861-0252','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实习租房时“房东”不让看房，要求先付押金才发地址。该怎么处理？','[\"先付\",\"核实房源、房东身份与合同，未核验前不转账\",\"交一半\",\"请室友代付\"]',1,'未核实房源就预付押金，可能遭遇虚假租房诈骗。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0253','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','租房合同署名与收款账户不一致，对方说“朋友代收”。该怎么处理？','[\"只拍聊天截图\",\"继续付款\",\"暂停并核实出租权、合同主体和收款原因\",\"现金交付即可\"]',2,'收款主体异常需核验，避免资金进入无关账户。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579861-0254','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','自称公安人员的人说你涉嫌洗钱，要求把钱转入“安全账户”接受审查。正确做法是？','[\"挂断电话，通过110或当地公安机关公开电话核实\",\"为证明清白立即转账\",\"按要求对家人保密\",\"把银行卡密码告诉对方\"]',0,'公检法机关没有所谓“安全账户”，不会通过电话要求转账自证清白。应挂断并通过公开渠道核实。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579861-0255','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','对方发来“警官证”和“通缉令”，要求你下载会议软件接受视频审讯并共享屏幕。你会怎么做？','[\"法律文书看起来正式，应配合\",\"拒绝共享屏幕，停止联系并通过官方渠道报警核实\",\"只共享手机桌面，不打开银行App\",\"找安静房间单独配合\"]',1,'证件和法律文书图片都可能伪造。诈骗分子会借共享屏幕窃取验证码和账户信息，并用“保密办案”隔离受害人。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0256','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“办案人员”要求你住进酒店、关闭其他通讯并不得告诉家人。该要求说明什么？','[\"案件级别很高，必须照做\",\"酒店网络更安全\",\"这是试图隔离受害人、阻断劝阻的高风险信号\",\"只要不转账就可以配合\"]',2,'冒充公检法诈骗常要求受害人保密、断联和转移到封闭环境，以逃避家人和警方劝阻。应立即停止联系并求助。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579861-0257','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是冒充公检法诈骗的常见话术？','[\"“你的身份证被冒用，涉嫌犯罪”\",\"“需要把钱转入安全账户核查”\",\"“不要告诉任何人，包括家人”\",\"“加QQ/微信，给你发通缉令”\"]',0,'冒充机关身份、制造恐慌、要求转账、阻止求助，常被组合使用。','approved','2026-10-17 09:49:41','[0,1,2,3]'),('UPLOAD-1792230579861-0258','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】现在互联网发达，为了提高工作效率，警察会通过网络或者电话联系你发送“逮捕令”、做笔录。','[\"正确\",\"错误\"]',1,'不要依据陌生来电或聊天软件中的所谓“逮捕令”转账或提供信息，应通过可信渠道核实。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0259','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你接到“公安局”电话，说你涉嫌洗钱，并强调“不要告诉任何人，否则以泄密罪处理”，你会怎么做？','[\"害怕，按对方指示操作\",\"直接挂断电话，实在不放心可以拨打110或去派出所咨询\",\"不告诉别人，泄密罪很严重的\",\"加对方微信，看看证据\"]',1,'挂断可疑电话后，自行通过110或派出所核实，不使用对方提供的联系方式。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0260','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新加入班级群的账号使用辅导员头像，通知每人立即转账缴纳“培训材料费”。你会怎么做？','[\"群里发的通知一定可靠\",\"通过原有联系方式或学院官方渠道向老师核实\",\"先转账避免错过截止时间\",\"把通知转发到其他班级\"]',1,'诈骗分子可能盗用老师头像或潜入群聊。涉及收费、转账时，必须通过原有联系方式或官方渠道二次确认。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0261','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','室友的社交账号发消息称手机坏了，急需你代转3000元。最佳做法是？','[\"语气很像本人，立即转账\",\"要求对方发一张自拍即可\",\"通过电话、视频或当面方式核验身份和事实\",\"先转一半表示信任\"]',2,'熟人账号可能被盗，文字语气和照片也可能被模仿或伪造。涉及资金应换一种独立渠道核实。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579861-0262','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实习期间，“单位领导”通过新账号联系你，要求代为转账并强调保密。你会怎么做？','[\"领导安排不能质疑\",\"先垫付个人资金\",\"删除聊天记录以便保密\",\"使用单位已知联系方式核实，并遵守财务审批流程\"]',3,'“更换账号、紧急、保密、代转账”是冒充领导诈骗的组合信号。任何付款都应遵循单位流程并独立核验。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579861-0263','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','电话里传来室友声音，说急需借钱但不能视频。你会怎么做？','[\"通过已保存号码回拨或当面核实\",\"马上转账\",\"让对方再说一句口头禅\",\"凭声音确认\"]',0,'声音可能被合成，应通过独立渠道核验身份和事由。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579861-0264','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','视频里的“导师”要求你代转项目经费到新账户。该怎么处理？','[\"视频能看见脸就可信\",\"通过已知电话和财务流程核实，不私自转账\",\"只转小额\",\"录屏后立即付款\"]',1,'换脸视频也可能伪造身份，资金操作须独立核实。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579861-0265','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人建议遭遇疑似AI冒充亲友要钱时，仅问一句“我们上次在哪吃饭”。这个办法是否充分？','[\"只看头像即可\",\"完全充分\",\"不充分，应通过原有联系方式或当面等独立渠道核实\",\"问生日即可\"]',2,'个人信息可能已泄露，单个私密问题不足以证明身份。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579861-0266','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“学院老师”用新号码说有紧急收费任务，催你不要问辅导员。该怎么处理？','[\"通过学院公开电话或已知联系方式核实\",\"只问对方姓名\",\"让室友先交\",\"立即转账\"]',0,'新号码、催促和阻止核实是组合风险信号。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0267','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','新生群里一个昵称为“班长”的账号发起教材费接龙，要求大家转到新收款码。你会怎么做？','[\"为了不耽误领书，先付再核实\",\"只看群昵称和头像就认定是班长\",\"请室友先转一笔试试\",\"通过已知联系方式向班长和课程负责人核实费用、收款人及领书安排\"]',3,'班级团购可能由学生代收，私人账户本身不必然是诈骗；关键是独立核实发起人、用途、金额和收款信息。若属学校统一收费，应按学校正式缴费渠道办理。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0268','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','社团团购群里的收款二维码突然更换，发码账号也不是原负责人。该怎么处理？','[\"先付一笔试试\",\"通过已知联系方式向负责人核实收款信息\",\"让其他同学先付\",\"认为群里发布就可信\"]',1,'群聊账号可能被冒用，付款前应独立核对收款人和订单。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0269','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','卖家以明显低价出售游戏账号，但要求离开正规平台到聊天软件交易。你会怎么做？','[\"低价机会难得，立即付款\",\"要到账号密码后再付款就一定安全\",\"坚持使用正规平台和担保流程，不进行私下转账\",\"让卖家提供身份证照片即可\"]',2,'私下交易失去平台保护，账号可能被找回，截图和身份材料也可能伪造。明显低价和催促脱离平台都是风险信号。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0270','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','虚假交易平台称因你填写银行卡号错误，账户被冻结，必须缴纳解冻费。你会怎么做？','[\"立即缴费避免账号永久冻结\",\"再注册一个账号继续交易\",\"提供短信验证码让客服修改\",\"停止付款，通过游戏官网或正规平台核实并报警咨询\"]',3,'“信息填错、资金冻结、缴费解冻”是游戏交易诈骗的常见套路。正规平台不会要求向个人或不明账户转账解冻。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0271','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你出售游戏账号时，买家发来二维码，称必须联系“平台客服”完成验资。正确做法是？','[\"只通过正规平台内置客服和订单页面处理\",\"扫码并按客服要求充值验资\",\"把支付密码告诉客服\",\"先转保证金再收款\"]',0,'假买家常伪造交易页面和客服，诱骗卖家支付保证金、解冻费。不要进入对方提供的外部客服页面。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0272','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你在游戏里卖账号，有买家说怕不安全，提议走其他平台交易，你会怎么做？','[\"只要能卖出好价，按买家要求换平台交易也可以\",\"联系买家，如果对方确实有购买意向再操作\",\"先试试，如果需要交费、验证码再退出也不迟\",\"意识到换平台交易是诈骗，立即停止操作\"]',3,'对方可能引导你进入虚假平台，再要求交费或提供账号信息。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0273','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是游戏交易诈骗的常见套路？','[\"发送虚假交易平台链接\",\"以“账户冻结”为由要求交解冻费\",\"私下交易，先钱后货\",\"在官方平台正常交易\"]',0,'陌生链接、额外收费和脱离平台私下交易都有明显风险。','approved','2026-10-17 09:49:41','[0,1,2]'),('UPLOAD-1792230579862-0274','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】游戏账号交易，最好选择官方交易平台或大型知名二手平台，不要点击陌生人发来的链接。','[\"正确\",\"错误\"]',0,'通过可信平台核实交易规则，不进入买家单独发来的交易页面。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0275','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“航空客服”准确说出你的姓名、航班和起飞时间，并称航班取消可获赔偿。你会怎么做？','[\"信息准确，直接按对方要求操作\",\"挂断后通过航空公司官网、官方App或购票平台主动核实\",\"把银行卡验证码告诉对方收取赔偿\",\"下载对方指定软件办理退款\"]',1,'航班信息可能因数据泄露被诈骗分子掌握。信息准确不等于来电真实，应主动使用官方渠道核验。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0276','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','对方以指导领取延误赔偿为由，要求开启屏幕共享并打开手机银行。应该怎么做？','[\"只要不说密码就安全\",\"遮住部分屏幕后继续\",\"拒绝共享屏幕，不在对方指导下操作账户\",\"先把资金转到余额较少的卡里\"]',2,'屏幕共享会暴露验证码、余额、账号和操作过程，诈骗分子还可能诱导开启远程控制。正规退赔不需要查看手机银行屏幕。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0277','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“航空客服”说赔偿通道需要验证账户，要求你先转一笔钱刷流水，之后会连同赔偿一起退回。正确判断是？','[\"小额验证很常见\",\"先转最低金额试试\",\"使用信用卡转账就没有风险\",\"这是诈骗高风险信号，正规退赔不会要求旅客先转账\"]',3,'任何以退款、赔偿为由要求受害人先转账、贷款、刷流水或缴纳保证金的行为都应警惕。应立即停止操作并联系官方客服。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0278','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','网贷平台称你已通过审核，但放款前必须先缴“保证金”和“刷流水费”。正确判断是？','[\"贷款行业都要先收费\",\"只交保证金即可\",\"这是高风险信号，应停止操作并核实平台资质\",\"借其他网贷支付费用\"]',2,'以无抵押、秒放款为诱饵，再要求放款前缴纳保证金、解冻费、刷流水费，是典型贷款诈骗套路。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0279','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','自称金融平台工作人员的人说你曾注册校园贷，不注销会影响征信，要求你从多个平台借款后转入“清算账户”。你会怎么做？','[\"按要求借款并转账\",\"只借一个平台试试\",\"开启屏幕共享证明自己没有贷款\",\"不转账，通过中国人民银行征信等官方渠道核实\"]',3,'征信记录不能通过向陌生账户转账来“注销”。凡要求借款、转账、刷流水以消除征信问题的，都是高风险诈骗话术。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0280','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','某机构承诺收取费用后可以删除真实的不良征信记录。正确认识是？','[\"征信异议应通过法定、官方渠道处理，付费“洗白”不可信\",\"内部人员可以随意删除记录\",\"只要收费不高就值得尝试\",\"把身份证和银行卡交给机构办理\"]',0,'正确的征信记录不能被所谓内部关系随意删除。发现错误记录应依法向金融机构或征信机构提出异议，不应向陌生机构付款或交出账户。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0281','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','公司承诺录用，但要求先办理分期贷款购买培训课程。该怎么处理？','[\"先申请额度\",\"立即贷款\",\"核实招聘真实性和合同，警惕“培训贷”\",\"让家长帮贷\"]',2,'招聘与贷款捆绑可能让求职者背负债务。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0282','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','同学借了网络贷款支付日常消费，催收人员又推荐“新平台借款还旧账”。你该建议他怎么做？','[\"先借新款，等毕业后再还\",\"把银行卡交给催收人员协商\",\"停止以贷养贷，保存合同和催收记录，向家人、学校资助部门或正规法律援助渠道求助\",\"把自己的实名账号借给他申请贷款\"]',2,'借新还旧会使债务和费用滚大；应核对实际债务与合同，不向陌生中介交出账户或再借高成本贷款。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0283','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“招聘专员”说远程面试需共享整部手机屏幕并打开银行App验证身份。该怎么处理？','[\"照做\",\"拒绝共享银行界面，核实招聘方身份\",\"只打开账户余额\",\"把验证码念给对方\"]',1,'正常招聘不需要查看银行操作，共享屏幕可能暴露敏感信息。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0284','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','实习单位要求交身份证原件和银行卡由公司“统一保管”。该怎么处理？','[\"只交银行卡\",\"请同学帮交\",\"交出\",\"拒绝交出原件和银行卡，核实单位及流程\"]',3,'证件与银行账户交由他人控制存在冒用和财产风险。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0285','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是防范培训诈骗的正确做法？','[\"查询培训机构有无办学资质\",\"仔细阅读合同中的退款条款\",\"保存招生简章、聊天记录和缴费凭证\",\"只要广告写得好，就可以直接报名\"]',0,'先核实机构、看清合同并留存证据，不能只依据广告付款。','approved','2026-10-17 09:49:41','[0,1,2]'),('UPLOAD-1792230579862-0286','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】培训机构承诺“学不会全额退款”，就说明这个机构很靠谱。','[\"正确\",\"错误\"]',1,'退款可能附带严格条件，应核实资质和具体合同条款。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0287','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你在网上看到“零基础学编程，三个月包就业，月薪过万”的广告，课程顾问承诺“100%推荐就业，否则全额退款”，你会怎么做？','[\"机会难得，马上报名\",\"先交一半费用，试试效果\",\"查询机构资质，仔细阅读合同条款后再决定\",\"叫上同学一起报名，可以砍价\"]',2,'应核实“包就业”“退款”等承诺的具体条件，谨慎付款。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0288','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你在路边看到“急招暑期兼职，日结300—500元，无需经验”的广告，联系后对方让你先交500元“保证金”，你会怎么做？','[\"500元换一份高薪工作，值得\",\"拒绝交钱，这是诈骗\",\"先交一半，剩下的入职后补\",\"介绍朋友也来应聘，分摊费用\"]',1,'以招聘为由要求先交保证金，是明显的风险信号。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0289','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是求职时的正确做法？','[\"通过学校就业指导中心找兼职\",\"去正规招聘网站或大型人才市场求职\",\"入职前签订劳动合同，看清条款\",\"只要是“高薪急聘”的工作，先抢到再说\"]',0,'应选择可靠渠道、核实招聘单位、看清工作和合同条件。','approved','2026-10-17 09:49:41','[0,1,2]'),('UPLOAD-1792230579862-0290','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】面试时对方说“这是行规，入职后钱会返还”，就可以放心交钱。','[\"正确\",\"错误\"]',1,'“入职后返还”不能证明收费合理，应警惕押金、报名费等要求。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0291','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】只要是好朋友拉你去的“好项目”，就一定不是传销。','[\"正确\",\"错误\"]',1,'熟人邀请不能证明项目合法，应独立核查其运作方式。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0292','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','你接到一个招聘电话，说你是“储备干部”，月薪8000起包吃住，工作地点在外地，你会怎么做？','[\"高薪工作，马上订票过去\",\"先问问同学有没有一起去的\",\"让对方先打5000元定金过来\",\"保持警惕，核实公司信息，告知家人朋友具体地址\"]',3,'异地高薪招聘应先核实公司、岗位及地址，并让可信任的人知道行程。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0293','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】传销组织最爱讲的“成功学”“国家项目”“一夜暴富”，属于洗脑话术。','[\"正确\",\"错误\"]',0,'借权威名义、夸大收益、承诺快速致富都是危险信号。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0294','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】以下哪些是传销的典型特征？','[\"承诺“一夜暴富”“月入过万”\",\"要求交纳入门费或购买产品\",\"需要拉人头发展下线\",\"限制人身自由，收走手机\"]',0,'交费、发展下线是重要识别线索；限制人身自由和收走手机也是危险信号。','approved','2026-10-17 09:49:41','[0,1,2,3]'),('UPLOAD-1792230579862-0295','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】如果不幸被困传销组织，以下哪些做法是正确的？','[\"立刻反抗，马上逃跑\",\"假装配合，寻找机会求救\",\"在钱币上写求救信息扔出窗外\",\"趁机记住周围环境特征，报警时提供\"]',1,'优先保证自身安全，寻找求救机会，并尽量记住位置和环境特征。采用隐蔽求救方式时，也要判断是否会带来更大危险。','approved','2026-10-17 09:49:41','[1,2,3]'),('UPLOAD-1792230579862-0296','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','收到短信称“奖学金待领取”，要求进入非学校域名填写银行卡密码。你会怎么做？','[\"通过学院或学校资助部门正式渠道核实\",\"先把链接转给室友\",\"只填密码不填姓名\",\"立即填写\"]',0,'奖助学金信息应从学校正式渠道核实，陌生链接索要银行口令是高风险信号。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0297','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','自称贷款“代办员”说缴纳服务费可保证助学贷款秒批，正确做法是？','[\"先交费\",\"查看教育部门和学校公布的办理方式，不向陌生人付费\",\"只付定金\",\"把证件原件寄给他\"]',1,'资助事项应走官方渠道，保证审批和预收费承诺不可信。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0298','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人冒充学校财务人员，称系统漏缴学费，要求转入个人账户。该怎么处理？','[\"先转一半\",\"立即转账\",\"通过学校缴费平台和财务处独立核实\",\"让同学代付\"]',2,'涉及收费应核对官方平台、收款主体和通知来源。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0299','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“项目秘书”私信称科研补贴到账前需扫码缴税，导师并未通知。该怎么处理？','[\"把码发给同组\",\"先交小额税款\",\"扫码\",\"通过导师和学院财务正式渠道核实\"]',3,'补贴发放不应依据陌生私信支付所谓前置费用。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0300','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','群里有人发“同学重病”募捐二维码，但无法核实当事人和渠道。该怎么处理？','[\"通过学院、当事人可信联系人或正规平台核实\",\"把二维码转给所有群\",\"只捐一元就安全\",\"立即转账\"]',0,'善意募捐也需要核实真实性与收款主体。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0301','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','“校友”请你帮忙接收一条验证码，称是参加讲座签到。该怎么处理？','[\"只发后四位\",\"让室友代收\",\"把验证码发给他\",\"拒绝并核实短信对应的操作，保护账号\"]',3,'验证码可能用于登录、绑定或支付，不应交给他人。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0302','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','投稿后有人自称期刊编辑，要求把“加急版面费”转至个人账户。该怎么处理？','[\"通过期刊官网公布的编辑部与缴费渠道核实\",\"先转一半\",\"只核对对方头像\",\"按邮件要求立即付款\"]',0,'学术投稿收费应核对真实期刊、正式通知和收款主体，不能仅凭来信转账。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0303','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人声称付费即可在学校系统里补录志愿服务时长，并索要学号密码。该怎么处理？','[\"拒绝并通过学校志愿服务管理渠道核实、反馈\",\"只提供学号\",\"让对方先做一小时\",\"交费并给密码\"]',0,'付费篡改记录的承诺不可信，账号密码泄露还可能带来进一步风险。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0304','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','有人冒充教务人员，称付“加急复核费”就能更改考试成绩。该怎么处理？','[\"先付费锁定名额\",\"私发学号和密码\",\"通过学校教务系统或学院核实正式复核流程\",\"请对方发个人收款码\"]',2,'成绩复核须走学校正式流程，私下收费和更改成绩承诺不可信。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0305','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','正准备向陌生账户转账时，接到96110来电，你会怎么做？','[\"暂停转账，听取预警并通过官方渠道核实\",\"告诉对方银行卡密码\",\"关机\",\"直接挂断继续转\"]',0,'96110是反诈预警劝阻专线，预警时应立即停止高风险操作。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0306','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','短信自称“反诈中心”，附陌生链接要求输入银行卡密码解除冻结。该怎么处理？','[\"按链接输入\",\"不点链接，通过110或官方反诈渠道核实\",\"先输入部分密码\",\"让同学帮忙填\"]',1,'防诈名义也可能被冒用，官方核验不应依赖来短信中的陌生链接。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0307','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','发现刚把钱转给诈骗账户，最重要的即时行动是？','[\"删除聊天记录\",\"等对方退款\",\"立即报警并联系银行或支付平台申请止付，保留交易记录\",\"继续转钱求解冻\"]',2,'及时报案和资金处置可能提高止损机会，证据也应保存。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0308','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','被骗后，下列哪组信息最有助于报案？','[\"删掉对话\",\"仅提供对方昵称\",\"只说“我被骗了”\",\"聊天记录、收款账号、转账凭证和时间线\"]',3,'完整交易和沟通记录便于警方核查。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0309','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','室友正被“客服”催促立刻转账，情绪紧张。你最好的帮助方式是？','[\"请他暂停操作，陪同从平台官方入口核实并必要时报警\",\"帮他加速付款\",\"代他保密\",\"当众指责他\"]',0,'先打断转账，再通过独立渠道核实，避免压力话术继续影响判断。','approved','2026-10-17 09:49:41','0'),('UPLOAD-1792230579862-0310','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','被骗后，有人自称“追回团队”要求先交追款费。该怎么处理？','[\"交费\",\"拒绝并向公安机关提供相关线索\",\"先交一半\",\"让团队远程控制手机\"]',1,'声称可收费追回资金的人可能实施二次诈骗。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0311','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','朋友发来“国家反诈中心新版安装包”的压缩文件，你会怎么做？','[\"把包转发全班\",\"直接安装\",\"从官方应用市场或官方渠道获取，不安装私发包\",\"关掉手机防护再装\"]',2,'安全工具也可能被仿冒，安装来源必须可靠。','approved','2026-10-17 09:49:41','2'),('UPLOAD-1792230579862-0312','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','朋友坚持向“投资导师”继续转钱，并拒绝听劝。你会怎么做？','[\"替导师作担保\",\"把聊天记录删掉\",\"帮他贷款\",\"尽快联系其可信亲友，协助报警或联系反诈劝阻渠道\"]',3,'持续转账风险高，应尽快争取可信的人和专业力量介入。','approved','2026-10-17 09:49:41','3'),('UPLOAD-1792230579862-0313','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','在校门口，一个陌生女生拦住你，说自己是隔壁学校的学生，手机钱包被偷了，想借你手机打电话，你会怎么做？','[\"看她很着急，把手机借给她\",\"帮她拨通电话，但手机不离开自己手\",\"与我无关，直接拒绝，转身离开\",\"如果她有学生证或者身份证，就可以给她\"]',1,'可以在确保自身安全的前提下帮忙，但不要让手机离开自己手中。','approved','2026-10-17 09:49:41','1'),('UPLOAD-1792230579862-0314','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【多选】遇到路边陌生人以“钱包被偷”“家人出车祸”等理由借钱，以下哪些做法是正确的？','[\"直接给钱，助人为乐\",\"告诉他“我可以帮你打110，警察会帮你”\",\"劝他去附近的警局求助\",\"不管真假，一律不理\"]',1,'可以引导对方向警方求助，避免直接交钱。截图中A项显示为绿色，但其内容与安全处置原则矛盾，正式入库前应核对原平台答案。（建议核对平台标准答案）','approved','2026-10-17 09:49:41','[1,2]'),('UPLOAD-1792230579862-0315','反诈骗','综合知识','基础','管理员上传：校园安全卫士题库_10.15整合.md','【判断】只要对方掏出身份证给我看，就说明他说的都是真的，可以放心借钱。','[\"正确\",\"错误\"]',1,'身份证不能证明借钱理由属实。','approved','2026-10-17 09:49:41','1');
