INSERT INTO `safety_cases` VALUES ('case-mtp9j08v-3a830d4c39ef','approved','消防安全','大型活动消防','南开大学党委保卫部、保卫处首页','https://guard.nankai.edu.cn/2026/0615/c10128a598341/page.htm','2026-06-15','2026-09-06','2026-09-13T04:33:19.495Z','{\"id\":\"case-mtp9j08v-3a830d4c39ef\",\"reviewStatus\":\"approved\",\"sourceType\":\"official\",\"sourceAuthority\":\"nankai\",\"sourceName\":\"南开大学党委保卫部、保卫处首页\",\"sourceUrl\":\"https://guard.nankai.edu.cn/2026/0615/c10128a598341/page.htm\",\"sourceIndexUrl\":\"https://guard.nankai.edu.cn/\",\"sourceOriginalTitle\":\"南开大学金融学院举办消防安全主题活动\",\"sourceExcerpt\":\"南开大学金融学院举办消防安全主题活动 发布者：保卫处 发布时间：2026-06-15 浏览次数： 10 为深入贯彻落实第 25个全国安全生产月 “人人讲安全、个个会应急” 主题要求，切实提升师生安全意识和应急处置能力， 6月10日，南开大学金融学院举办 “筑牢消防安全基石 守护师生健康平安”主题消防安全活动 。此次活动贯穿大安全理念，包括 消防疏散与灭火演练、启动仪式、安全讲座、心脏急救及健身锻炼培训 等多个环节，学院师生、物业及安保人员共同参与。 下午 13时20分，随着消防警铃在金融学院大楼响起，消防疏散演练正式开始。全体师生及物业人员 迅速响应，按照应急指示牌指引，有序疏散至楼前广场 。随后，在南开大学党委保卫部老师的指导下，师生们分批进行了 灭火器、室内消火栓等消防器材的实操演练 ，亲身体验了 “提拔握压”等灭火要领，有效提升了扑救初起火灾的实战能力。 活动启动仪式及专题培训在学院 201报告厅举行。新华网基层应急联合运营总监、《学习强国》“安全教育故事荟”栏目副总监、中央党校中国应急管理学会安全教育工作委员会秘书长 王首越 ，国家安全科普专家、中国社区发展协会应急委副主任 谷学亮 ，南开大学党委保卫部副部长 阴沛涞 ，校医院副院长 陶慧 ，金融学院党委书记 张尧 ，党委副书记、副院长 高珊 ， 保卫部 安全科相关负责人、 校医院 医师代表、 体育部 教师代表、 校友 代表、 金融学院 师生代表及 物业服务 保障人员共同参会。金融学院副院长 王越超 主持活动。 张尧 在致辞中强调， 消防安全与应急急救不仅是安全意识问题，更是需要系统学习的科学知识 。他强调，掌握灭火器使用、心肺复苏等技能，既是为了保护自己，更是在关键时刻挺身而出、救助他人、守护集体的责任担当， 希望师生将安全意识融入日常 ，共同筑牢平安校园基石。 王首越 结合自身经历，深刻阐述了 “把安全避险能力练成第一反应” 的重要性。他呼吁师生将应急知识 从 “知道”转化为“做到” ，并将安全理念传递给家人与社会，推动形成全民讲安全、会应急的良好氛围。 党委保卫部安全科科长 李娜 对学校新颁布的 《南开大学消防安全管理规定》 等五项安全制度进行了详细解读，重点讲解了消防安全责任制、动火作业审批、公共秩序维护、电动自行车管理、机动车门禁与道路管理等内容，要求师生 “人人知晓原则，人人敬畏底线” ，共同维护校园安全环境。 金融系 1991级校友集体为学院捐赠 AED (自动体外除颤器) ，校友代表 仲书田 在致辞中深情回顾了求学时光，结合金融行业 “一点不能差，差一点不行” 的安全理念，勉励学弟学妹重视每一次安全教育活动。他表示，无论是校园生活还是未来职场，安全意识都应内化为日常习惯，希望同学们珍视学院对学生的关怀与守护，实现一生平安。 校医院副院长 陶慧 深情回忆了从事医疗服务和救助工作的经历，介绍了 心肺复苏及 AED设备使用的科学性与重要性 ，表示校医院将全力守护师生健康。 体育部教师代表 韩轩承 从运动前 热身、量力而行、自我保护 等方面，强调了科学锻炼的安全要点。 启动仪式后，学院开展了 心肺复苏及 AED急救专项培训 ，健身房同步进行了安全健身实操指导。 本次活动内容丰富、形式多样，理论与实践紧密结合，切实增强了师生的安全意识与应急避险能力。金融学院将以此次活动为契机， 持续深化安全教育，完善安全管理长效机制 ，为师生健康平安和学院高质量发展筑牢坚实防线。  \",\"sourceFetchError\":\"\",\"sourceDate\":\"2026-06-15\",\"collectedAt\":\"2026-09-06\",\"safetyType\":\"消防安全\",\"campusScene\":\"大型活动消防\",\"title\":\"南开大学金融学院举办消防安全主题活动\",\"subtitle\":\"官方来源自动采集\",\"sceneClass\":\"scene-task\",\"desensitization\":\"无需要脱敏的信息。\",\"actor\":\"同学\",\"peer\":\"同学\",\"authority\":\"学校相关部门\",\"hook\":\"学校师生在校内发现有火情。\",\"firstLure\":\"\",\"escalation\":\"如果置之不理，火势会变大，造成沉重的后果。\",\"pressure\":\"\",\"riskyChoice\":\"\",\"safeChoice\":\"\",\"helperAction\":\"\",\"wrongHelp\":\"\",\"warningSigns\":[\"以火情有专业人士来处理而忽视\",\"不熟悉消防器械的使用\",\"人员聚集\",\"踩踏事件\"],\"safeActions\":[\"不携带火源进入校园\",\"不携带易燃易爆物品进入校园\",\"及时向保卫处\",\"119寻求帮助\"],\"duplicateCheck\":{\"status\":\"unique\",\"score\":0,\"matchedCaseId\":\"\",\"reason\":\"text-similarity\",\"checkedAt\":\"2026-09-06\"},\"desensitizationAudit\":{\"identity\":\"not_involved\",\"location\":\"not_involved\",\"account\":\"not_involved\",\"amount\":\"not_involved\"},\"sanitizedSourceText\":\"随着消防警铃在金融学院大楼响起，消防疏散演练正式开始。全体师生及物业人员 迅速响应，按照应急指示牌指引，有序疏散至楼前广场 。随后，在南开大学党委保卫部老师的指导下，师生们分批进行了 灭火器、室内消火栓等消防器材的实操演练 ，亲身体验了 “提拔握压”等灭火要领，有效提升了扑救初起火灾的实战能力。\",\"updatedAt\":\"2026-09-13T04:33:19.495Z\",\"reviewNote\":\"\",\"reviewedAt\":\"2026-10-17\"}'),('case-mtp9j0p8-71eb0fa5f0ff','draft','网络安全','待分类情景','南开大学网信办网络安全栏目','https://wxb.nankai.edu.cn/info/1074/1698.htm','2025-07-28','2026-09-06','2026-11-11T16:00:02.443Z','{\"id\":\"case-mtp9j0p8-71eb0fa5f0ff\",\"reviewStatus\":\"draft\",\"sourceType\":\"official\",\"sourceAuthority\":\"nankai\",\"sourceName\":\"南开大学网信办网络安全栏目\",\"sourceUrl\":\"https://wxb.nankai.edu.cn/info/1074/1698.htm\",\"sourceIndexUrl\":\"https://wxb.nankai.edu.cn/\",\"sourceOriginalTitle\":\"关于“南开大学”企业微信的重要提示\",\"sourceExcerpt\":\"关于“南开大学”企业微信的重要提示-南开大学党委网络安全和信息化办公室 首页 部门概况 部门简介 机构设置 规章制度 规划建设 网络安全 数据管理 运维管理 服务中心 通知公告 计算平台科 数据管理科 信息科 综合管理科（内设） 业务办理 成果展示 下载专区 常见问题 一卡通 邮箱 统一身份认证 网络报修 VPN 无感知使用说明 移动设备关闭随机MAC地址 党委网络安全和信息化办公室 大数据管理中心 首页 部门概况 部门简介 机构设置 规章制度 规划建设 网络安全 数据管理 运维管理 服务中心 通知公告 计算平台科 数据管理科 信息科 综合管理科（内设） 业务办理 成果展示 下载专区 常见问题 一卡通 邮箱 统一身份认证 网络报修 VPN 无感知使用说明 移动设备关闭随机MAC地址 安全公告 SECURITY NOTICE 当前位置: 首页 > 正文 关于“南开大学”企业微信的重要提示 发布时间：2025-07-28 浏览次数： 各位师生：     近期接师生反映，收到微信平台推送的 “加入南开大学企业微信” 邀请通知。经核实，我校企业微信“南开大学”已于2020年正式停用，所有校内协同服务均已迁移至飞书平台，且此后未再注册或启用任何企业微信账号。当前微信端相关邀请系第三方平台自动推广行为，非学校官方发起，与我校无任何关联，请各位师生请勿点击此类链接或进行相关操作，避免个人信息泄露。 特此提醒，敬请周知。 党委网络安全和信息化办公室 大数据管理中心 联系我们 八里台校区： 天津市南开区卫津路94号 [300071] 津南校区： 天津海河教育园区同砚路38号 [300350] 泰达校区： 天津经济开发区宏达街23号 [300457] 校园卡业务： 八里台 022-23508231 津南 022-85358890转19号窗口 邮箱： nkecard@nankai.edu.cn 网络报修： 八里台 022-23503656  津南 022-85358100 泰达 022-66228421 办公邮箱： wxb@nankai.edu.cn 常用链接 南开大学 VPN服务 信息门户 邮箱 版权所有:南开大学党委网络安全和信息化办公室、大数据管理中心 津ICP备14001543号-2 津公网安备：12019202000194\",\"sourceFetchError\":\"\",\"sourceDate\":\"2025-07-28\",\"collectedAt\":\"2026-09-06\",\"safetyType\":\"网络安全\",\"campusScene\":\"待分类情景\",\"title\":\"关于“南开大学”企业微信的重要提示\",\"subtitle\":\"官方来源自动采集\",\"sceneClass\":\"scene-task\",\"desensitization\":\"待完善：需由编辑员完成信息脱敏说明。\",\"actor\":\"同学\",\"peer\":\"同学\",\"authority\":\"学校相关部门\",\"hook\":\"官方来源提到“2025-07 28 关于“南开大学”企业微信的重要提示 各位师生： 近期接师生反映，收到微信平台推送的 “加入南开大学企业微信” 邀请通知。经核实，我校企业微信“南开大学”已于2020年正式停用，所有校内协同服务均已迁移至飞书平台，且此后未再注册或启用任何企业微信账号。当前微信端相关邀请系第三方平台自动推广行为，非学校官方发起，与我校无任何关联，请各位师生请勿点击此类链接或进行相关操作，避免个人信息泄露。 特此提醒，敬请周知。”，需由编辑员整理为校园安全情景。\",\"firstLure\":\"\",\"escalation\":\"待编辑员补充风险升级过程。\",\"pressure\":\"\",\"riskyChoice\":\"\",\"safeChoice\":\"\",\"helperAction\":\"\",\"wrongHelp\":\"\",\"warningSigns\":[\"官方来源提示风险\",\"需进一步提炼风险信号\",\"需完成信息脱敏\"],\"safeActions\":[\"查看官方来源\",\"完成信息脱敏\",\"补充处置建议\"],\"duplicateCheck\":{\"status\":\"unique\",\"score\":0.284,\"matchedCaseId\":\"case-mtp9j08v-3a830d4c39ef\",\"reason\":\"text-similarity\",\"checkedAt\":\"2026-09-06\"},\"updatedAt\":\"2026-11-11T16:00:02.443Z\"}'),('case-mtp9j0q9-a4e7c427433b','approved','网络安全','钓鱼链接','南开大学网信办网络安全栏目','https://wxb.nankai.edu.cn/info/1074/1704.htm','2025-06-30','2026-09-06','2026-11-11T16:00:02.474Z','{\"id\":\"case-mtp9j0q9-a4e7c427433b\",\"reviewStatus\